/// Machine architecture accepted by the general AOT object pipeline.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum Architecture {
    X86_64,
    Aarch64,
}

/// Operating system whose object and symbol conventions are requested.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum OperatingSystem {
    Linux,
    Macos,
}

/// C calling convention used by the emitted entry point.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum CallAbi {
    /// The AMD64 System V ABI used by Linux and macOS.
    SystemV,
    /// The `AArch64` procedure call standard used by Linux and macOS.
    Aapcs64,
}

/// One independently represented target CPU feature.
///
/// This is a vocabulary, not an ordered list of optimization levels. In
/// particular, AVX-512 subfeatures remain separate facts so a future lowering
/// can request exactly the instructions it emits.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
#[repr(u8)]
pub enum CpuFeature {
    X86Sse2 = 0,
    X86Avx2 = 1,
    X86Avx512F = 2,
    X86Avx512Bw = 3,
    X86Avx512Vl = 4,
    Aarch64Asimd = 32,
    Aarch64Sve = 33,
    Aarch64Sve2 = 34,
}

impl CpuFeature {
    const fn bit(self) -> u64 {
        match self {
            Self::X86Sse2 => 1_u64 << 0,
            Self::X86Avx2 => 1_u64 << 1,
            Self::X86Avx512F => 1_u64 << 2,
            Self::X86Avx512Bw => 1_u64 << 3,
            Self::X86Avx512Vl => 1_u64 << 4,
            Self::Aarch64Asimd => 1_u64 << 32,
            Self::Aarch64Sve => 1_u64 << 33,
            Self::Aarch64Sve2 => 1_u64 << 34,
        }
    }
}

/// A non-linear set of CPU feature facts.
#[derive(Clone, Copy, Default, Eq, Hash, PartialEq)]
pub struct FeatureSet(u64);

impl FeatureSet {
    pub const EMPTY: Self = Self(0);

    const KNOWN_BITS: u64 = CpuFeature::X86Sse2.bit()
        | CpuFeature::X86Avx2.bit()
        | CpuFeature::X86Avx512F.bit()
        | CpuFeature::X86Avx512Bw.bit()
        | CpuFeature::X86Avx512Vl.bit()
        | CpuFeature::Aarch64Asimd.bit()
        | CpuFeature::Aarch64Sve.bit()
        | CpuFeature::Aarch64Sve2.bit();

    /// Construct a set containing one feature.
    #[must_use]
    pub const fn of(feature: CpuFeature) -> Self {
        Self(feature.bit())
    }

    /// Decode a feature mask, rejecting unknown vocabulary bits.
    #[must_use]
    pub const fn from_bits(bits: u64) -> Option<Self> {
        if bits & !Self::KNOWN_BITS == 0 {
            Some(Self(bits))
        } else {
            None
        }
    }

    /// Return the stable bit representation.
    #[must_use]
    pub const fn bits(self) -> u64 {
        self.0
    }

    /// Return whether this set has no features.
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }

    /// Return a copy with `feature` present.
    #[must_use]
    pub const fn with(self, feature: CpuFeature) -> Self {
        Self(self.0 | feature.bit())
    }

    /// Return the union of two independent feature sets.
    #[must_use]
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }

    /// Return whether every bit in `required` is present.
    #[must_use]
    pub const fn contains(self, required: Self) -> bool {
        self.0 & required.0 == required.0
    }

    const fn is_for_architecture(self, architecture: Architecture) -> bool {
        let x86 = CpuFeature::X86Sse2.bit()
            | CpuFeature::X86Avx2.bit()
            | CpuFeature::X86Avx512F.bit()
            | CpuFeature::X86Avx512Bw.bit()
            | CpuFeature::X86Avx512Vl.bit();
        let aarch64 = CpuFeature::Aarch64Asimd.bit()
            | CpuFeature::Aarch64Sve.bit()
            | CpuFeature::Aarch64Sve2.bit();
        match architecture {
            Architecture::X86_64 => self.0 & !x86 == 0,
            Architecture::Aarch64 => self.0 & !aarch64 == 0,
        }
    }

    const fn has(self, feature: CpuFeature) -> bool {
        self.0 & feature.bit() != 0
    }
}

impl core::fmt::Debug for FeatureSet {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        formatter
            .debug_struct("FeatureSet")
            .field("bits", &format_args!("{:#018x}", self.0))
            .finish()
    }
}

/// Complete native compilation target.
///
/// `features` records capabilities made available to lowering. The scalar
/// runtime adapter emitted today does not itself require any optional feature.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct Target {
    pub architecture: Architecture,
    pub operating_system: OperatingSystem,
    pub abi: CallAbi,
    pub features: FeatureSet,
}

impl Target {
    /// Construct a validated target, deriving its ABI from the architecture.
    ///
    /// # Errors
    ///
    /// Returns [`ObjectError::UnsupportedTarget`] for cross-architecture
    /// features or an invalid feature dependency.
    pub fn new(
        architecture: Architecture,
        operating_system: OperatingSystem,
        features: FeatureSet,
    ) -> Result<Self, ObjectError> {
        let abi = match architecture {
            Architecture::X86_64 => CallAbi::SystemV,
            Architecture::Aarch64 => CallAbi::Aapcs64,
        };
        Self::from_parts(architecture, operating_system, abi, features)
    }

    /// Construct and validate every explicit target component.
    ///
    /// # Errors
    ///
    /// Returns [`ObjectError::UnsupportedTarget`] when the ABI, feature
    /// architecture, or feature dependencies are inconsistent.
    pub fn from_parts(
        architecture: Architecture,
        operating_system: OperatingSystem,
        abi: CallAbi,
        features: FeatureSet,
    ) -> Result<Self, ObjectError> {
        let target = Self {
            architecture,
            operating_system,
            abi,
            features,
        };
        target.validate()?;
        Ok(target)
    }

    /// Portable x86-64 Linux target.
    #[must_use]
    pub const fn x86_64_linux() -> Self {
        Self {
            architecture: Architecture::X86_64,
            operating_system: OperatingSystem::Linux,
            abi: CallAbi::SystemV,
            features: FeatureSet::EMPTY,
        }
    }

    /// Portable x86-64 macOS target.
    #[must_use]
    pub const fn x86_64_macos() -> Self {
        Self {
            architecture: Architecture::X86_64,
            operating_system: OperatingSystem::Macos,
            abi: CallAbi::SystemV,
            features: FeatureSet::EMPTY,
        }
    }

    /// Portable `AArch64` Linux target.
    #[must_use]
    pub const fn aarch64_linux() -> Self {
        Self {
            architecture: Architecture::Aarch64,
            operating_system: OperatingSystem::Linux,
            abi: CallAbi::Aapcs64,
            features: FeatureSet::EMPTY,
        }
    }

    /// Portable `AArch64` macOS target.
    #[must_use]
    pub const fn aarch64_macos() -> Self {
        Self {
            architecture: Architecture::Aarch64,
            operating_system: OperatingSystem::Macos,
            abi: CallAbi::Aapcs64,
            features: FeatureSet::EMPTY,
        }
    }

    /// Return this target with a validated capability set.
    ///
    /// # Errors
    ///
    /// Returns [`ObjectError::UnsupportedTarget`] for features belonging to a
    /// different architecture or for an incomplete dependency set.
    pub fn with_features(mut self, features: FeatureSet) -> Result<Self, ObjectError> {
        self.features = features;
        self.validate()?;
        Ok(self)
    }

    /// Validate the target tuple and explicit feature dependencies.
    ///
    /// # Errors
    ///
    /// Returns [`ObjectError::UnsupportedTarget`] for an incoherent tuple.
    pub fn validate(self) -> Result<(), ObjectError> {
        let abi_matches = matches!(
            (self.architecture, self.abi),
            (Architecture::X86_64, CallAbi::SystemV) | (Architecture::Aarch64, CallAbi::Aapcs64)
        );
        if !abi_matches || !self.features.is_for_architecture(self.architecture) {
            return Err(ObjectError::UnsupportedTarget);
        }

        // These are explicit extension dependencies, not a linear feature
        // tier. AVX2 and AVX-512F, for example, remain independent facts.
        if self.features.has(CpuFeature::X86Avx512Bw) && !self.features.has(CpuFeature::X86Avx512F)
        {
            return Err(ObjectError::UnsupportedTarget);
        }
        if self.features.has(CpuFeature::X86Avx512Vl) && !self.features.has(CpuFeature::X86Avx512F)
        {
            return Err(ObjectError::UnsupportedTarget);
        }
        if self.features.has(CpuFeature::Aarch64Sve2) && !self.features.has(CpuFeature::Aarch64Sve)
        {
            return Err(ObjectError::UnsupportedTarget);
        }
        Ok(())
    }
}

/// Logical kind of a module section.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum SectionKind {
    Text,
    ReadOnlyData,
}

/// Start-state accelerator actually emitted in a native module.
///
/// `None` means no start scanner was emitted: the module may use the runtime
/// adapter, or its selected native route, target backend, or graph-derived
/// filter cost model may have retained scalar transition work.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum StartAccelerator {
    None,
    Scalar,
    X86Sse2,
    X86Avx2,
    X86Avx512Bw,
    Aarch64Asimd,
    Aarch64Sve,
    Aarch64Sve2,
}

/// Target instruction family that actually implemented one emitted primary
/// scanner. This private receipt is produced by the backend, not inferred by
/// the planner, so retained-fallback publication can authenticate the code
/// that was generated rather than merely the intended layout.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeScannerIsa {
    ScalarEmpty,
    X86ScalarBitmap,
    X86Sse2,
    X86Avx2,
    X86Avx512Bw,
    Aarch64ScalarRange,
    Aarch64ScalarLut,
    Aarch64Asimd,
    Aarch64Sve,
    Aarch64Sve2,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct NativeScannerEmission {
    scan_offset: u8,
    membership: [u64; 4],
    isa: NativeScannerIsa,
    vectorized: bool,
}

struct NativeDfaEmission {
    code: Vec<u8>,
    relocations: Vec<ModuleRelocation>,
    scanner: Option<NativeScannerEmission>,
    suffix_scanner: Option<NativeScannerEmission>,
    conjunction: Option<NativeVectorConjunctionEmission>,
}

struct NativeDynamicRowsEmission {
    code: Vec<u8>,
    relocations: Vec<ModuleRelocation>,
    scanner: Option<NativeScannerEmission>,
}

/// Target-neutral representation selected for one graph-certified dynamic
/// root. Compact range filters retain their established immediate-constant
/// lowering. Every other nontrivial membership is represented by the same
/// canonical bitmap/nibble tables used by retained native DFA roots.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeDynamicRootPlan {
    Range(NativeStartFilter),
    Exact(NativeExactByteSet),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum X86DynamicRootPlan {
    Range(NativeStartFilter),
    Exact {
        set: NativeExactByteSet,
        storage: NativeExactByteSetStorage,
    },
}

/// Concrete `AArch64` lowering selected for one graph-certified dynamic root.
///
/// Table offsets are relative to the byte immediately following the embedded
/// 32-byte artifact identity. Keeping that base distinct lets preflight retain
/// the identity symbol unchanged while optional scanner constants are appended
/// transactionally after it.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(
    clippy::struct_excessive_bools,
    reason = "the booleans receipt independent target routes and lowering resources"
)]
struct Aarch64DynamicRootPlan {
    filter: NativeStartFilter,
    sve_kind: Option<Aarch64SveFilterKind>,
    use_asimd: bool,
    use_asimd_batch: bool,
    use_exact_asimd_lane: bool,
    use_runtime_vl_dispatch: bool,
    lane_index_offset: Option<u32>,
    scanner: NativeScannerEmission,
}

impl Aarch64DynamicRootPlan {
    const fn uses_sve(self) -> bool {
        self.sve_kind.is_some()
    }

    const fn has_tables(self) -> bool {
        self.lane_index_offset.is_some()
            || matches!(
                self.sve_kind,
                Some(Aarch64SveFilterKind::Sve2 { .. })
            )
    }
}

/// Table-backed arbitrary-membership lowering for one dynamic `AArch64` root.
/// All offsets are relative to the byte immediately after the artifact
/// identity, matching [`Aarch64DynamicRootPlan`]'s range-table convention.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Aarch64DynamicExactRootPlan {
    set: NativeExactByteSet,
    storage: NativeExactByteSetStorage,
    sve_kind: Option<Aarch64ExactSveKind>,
    use_asimd: bool,
    use_exact_asimd_lane: bool,
    use_runtime_vl_dispatch: bool,
    lane_index_offset: Option<u32>,
    scanner: NativeScannerEmission,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Aarch64DynamicScannerPlan {
    Range(Aarch64DynamicRootPlan),
    Exact(Aarch64DynamicExactRootPlan),
}

impl Aarch64DynamicScannerPlan {
    const fn scanner(self) -> NativeScannerEmission {
        match self {
            Self::Range(plan) => plan.scanner,
            Self::Exact(plan) => plan.scanner,
        }
    }

    const fn has_tables(self) -> bool {
        match self {
            Self::Range(plan) => plan.has_tables(),
            Self::Exact(_) => true,
        }
    }

    const fn uses_sve(self) -> bool {
        match self {
            Self::Range(plan) => plan.uses_sve(),
            Self::Exact(plan) => plan.sve_kind.is_some(),
        }
    }

    const fn uses_asimd(self) -> bool {
        match self {
            Self::Range(plan) => plan.use_asimd,
            Self::Exact(plan) => plan.use_asimd,
        }
    }
}

/// Validation contract at one emitted native-DFA entry.
///
/// Public entries validate every raw ABI argument and initialize their public
/// two-word result before running any scanner. The prepared partial entry has
/// a distinct, local-only core symbol. Its caller has already validated the
/// public haystack, length, and output, and the authenticated preflight returns
/// a bounded exact window. Unlike a public entry, the local core returns match
/// and continuation payloads in caller-saved registers; its wrapper publishes
/// public output or marshals the continuation only after classifying status.
/// A match uses x86 R10/R11 or AArch64 X6/X7 for start/end (SelectedEnd uses
/// only the latter). A resume uses x86 R10/RDX/R11 or AArch64 X6/X2/X7 for
/// state/position/pending-end. The canonical resume state already authenticates
/// whether a pending endpoint exists, so the endpoint register is ignored for
/// a no-pending state and need not be materialized by Exists.
/// That local contract may therefore enter after the raw checks without
/// weakening any public boundary.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NativeDfaEntryContract {
    Public,
    PreparedPartialCore,
}

impl NativeScannerEmission {
    const fn start_accelerator(self) -> StartAccelerator {
        match self.isa {
            NativeScannerIsa::ScalarEmpty
            | NativeScannerIsa::X86ScalarBitmap
            | NativeScannerIsa::Aarch64ScalarRange
            | NativeScannerIsa::Aarch64ScalarLut => {
                StartAccelerator::Scalar
            }
            NativeScannerIsa::X86Sse2 => StartAccelerator::X86Sse2,
            NativeScannerIsa::X86Avx2 => StartAccelerator::X86Avx2,
            NativeScannerIsa::X86Avx512Bw => StartAccelerator::X86Avx512Bw,
            NativeScannerIsa::Aarch64Asimd => StartAccelerator::Aarch64Asimd,
            NativeScannerIsa::Aarch64Sve => StartAccelerator::Aarch64Sve,
            NativeScannerIsa::Aarch64Sve2 => StartAccelerator::Aarch64Sve2,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Aarch64PrimaryScannerIsa {
    Scalar,
    Asimd,
    Sve,
    SveWithAsimdVl16,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Aarch64MixedVectorPreference {
    #[allow(
        dead_code,
        reason = "the alternate policy is retained for source-identical qualification and tests"
    )]
    PreferAsimd,
    PreferSve,
}

/// Explicit Linux policy for a target that reports both fixed-width ASIMD and
/// scalable SVE. Feature bits remain capabilities: this preference is applied
/// only after the current primary route proves that its shape has an SVE
/// lowering. Supported mixed routes select ASIMD at runtime when `CNTB` is 16
/// and scalable SVE above that width. Unsupported SVE route shapes fall
/// through to ASIMD. Suffix accelerators apply the same policy independently
/// after proving their own graph-derived scalable route; loop accelerators
/// retain their independent ASIMD choice.
///
/// Keeping the preference as one private switch also permits source-identical
/// native A/B qualification without consulting pattern names or input data.
const AARCH64_LINUX_MIXED_VECTOR_PREFERENCE: Aarch64MixedVectorPreference =
    Aarch64MixedVectorPreference::PreferSve;

fn aarch64_primary_scanner_isa_with_policy(
    operating_system: OperatingSystem,
    features: FeatureSet,
    sve_route_supported: bool,
    mixed_preference: Aarch64MixedVectorPreference,
) -> Aarch64PrimaryScannerIsa {
    let has_asimd = features.has(CpuFeature::Aarch64Asimd);
    let has_sve = operating_system == OperatingSystem::Linux
        && features.has(CpuFeature::Aarch64Sve)
        && sve_route_supported;
    match (has_asimd, has_sve) {
        (true, true) => match mixed_preference {
            Aarch64MixedVectorPreference::PreferAsimd => Aarch64PrimaryScannerIsa::Asimd,
            Aarch64MixedVectorPreference::PreferSve => {
                Aarch64PrimaryScannerIsa::SveWithAsimdVl16
            }
        },
        (true, false) => Aarch64PrimaryScannerIsa::Asimd,
        (false, true) => Aarch64PrimaryScannerIsa::Sve,
        (false, false) => Aarch64PrimaryScannerIsa::Scalar,
    }
}

const fn aarch64_primary_scanner_uses_sve(isa: Aarch64PrimaryScannerIsa) -> bool {
    matches!(
        isa,
        Aarch64PrimaryScannerIsa::Sve | Aarch64PrimaryScannerIsa::SveWithAsimdVl16
    )
}

const fn aarch64_primary_scanner_uses_runtime_vl_dispatch(
    isa: Aarch64PrimaryScannerIsa,
) -> bool {
    matches!(isa, Aarch64PrimaryScannerIsa::SveWithAsimdVl16)
}

fn aarch64_primary_scanner_isa(
    operating_system: OperatingSystem,
    features: FeatureSet,
    sve_route_supported: bool,
) -> Aarch64PrimaryScannerIsa {
    aarch64_primary_scanner_isa_with_policy(
        operating_system,
        features,
        sve_route_supported,
        AARCH64_LINUX_MIXED_VECTOR_PREFERENCE,
    )
}

/// One independent section before object-format layout.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ModuleSection {
    pub name: &'static str,
    pub kind: SectionKind,
    pub alignment: u64,
    pub data: Box<[u8]>,
}

impl ModuleSection {
    /// Return the immutable section payload.
    #[must_use]
    pub fn bytes(&self) -> &[u8] {
        &self.data
    }
}

/// Linker visibility for a module symbol.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum SymbolBinding {
    Local,
    Global,
}

/// Linker type for a module symbol.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum SymbolKind {
    Function,
    Object,
}

/// One defined or undefined object symbol.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ModuleSymbol {
    pub name: String,
    pub binding: SymbolBinding,
    pub kind: SymbolKind,
    /// Defining section index, or `None` for an undefined external symbol.
    pub section: Option<usize>,
    /// Section-relative value. Undefined symbols must use zero.
    pub offset: u64,
    pub size: u64,
}

/// Relocation operation understood by both generic object writers.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum RelocationKind {
    /// AMD64 signed 32-bit PC-relative data address.
    X86PcRelative32,
    /// AMD64 signed 32-bit PLT-capable branch.
    X86PltRelative32,
    /// `AArch64` page-relative ADRP immediate.
    Aarch64Page21,
    /// `AArch64` low-12-bit ADD immediate paired with an ADRP.
    Aarch64PageOff12,
    /// `AArch64` unconditional 26-bit branch.
    Aarch64Branch26,
}

/// One unresolved, section-relative relocation.
///
/// Addends use the ELF mathematical convention (`S + A - P`). Object writers
/// whose relocation implicitly uses the end of an encoded field must translate
/// from this representation.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct ModuleRelocation {
    /// Index in [`CompiledModule::sections`].
    pub section: usize,
    /// Offset of the relocation field or instruction within `section`.
    pub offset: u64,
    pub kind: RelocationKind,
    /// Index in [`CompiledModule::symbols`].
    pub symbol: usize,
    pub addend: i64,
}

/// Object-format-neutral native module.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct CompiledModule {
    target: Target,
    sections: Box<[ModuleSection]>,
    symbols: Box<[ModuleSymbol]>,
    relocations: Box<[ModuleRelocation]>,
    entry_symbol_index: usize,
    prepared_entry_symbol_index: Option<usize>,
    runtime_symbol_index: Option<usize>,
    runtime_program_symbol_index: Option<usize>,
    start_accelerator: StartAccelerator,
    anchored_prefix_filter_bytes: u8,
    slow_aot_report: Option<SlowAotReport>,
    slow_context_aot_report: Option<SlowContextAotReport>,
    slow_retained_forward_minimized: bool,
}

