    #[test]
    fn retained_prefix_publication_requires_exact_vector_scanner() {
        let mut ranges = [EMPTY_NATIVE_BYTE_RANGE; MAX_START_FILTER_RANGES];
        ranges[0] = NativeByteRange { start: 1, end: 1 };
        ranges[1] = NativeByteRange { start: 3, end: 3 };
        let filter = NativeStartFilter {
            ranges,
            range_count: 2,
            candidate_bytes: 2,
            scan_offset: 4,
            from_anchored_prefix: true,
        };
        let requirement = NativeRetainedPrefixRequirement {
            scan_offset: 4,
            membership: [0b1010, 0, 0, 0],
        };
        let emission = NativeScannerEmission {
            scan_offset: filter.scan_offset,
            membership: start_filter_membership(filter).unwrap(),
            isa: NativeScannerIsa::X86Sse2,
            vectorized: true,
        };
        assert!(retained_prefix_scanner_is_preserved(
            Some(emission),
            requirement
        ));
        assert!(!retained_prefix_scanner_is_preserved(
            Some(NativeScannerEmission {
                vectorized: false,
                ..emission
            }),
            requirement
        ));
        assert!(exact_position_scanner_semantics_are_preserved(
            Some(NativeScannerEmission {
                isa: NativeScannerIsa::Aarch64ScalarRange,
                vectorized: false,
                ..emission
            }),
            requirement.scan_offset,
            requirement.membership,
        ));
        assert!(!retained_prefix_scanner_is_preserved(None, requirement));
        assert!(!retained_prefix_scanner_is_preserved(
            Some(NativeScannerEmission {
                scan_offset: 3,
                ..emission
            }),
            requirement
        ));
        assert!(!retained_prefix_scanner_is_preserved(
            Some(NativeScannerEmission {
                membership: [0b1110, 0, 0, 0],
                ..emission
            }),
            requirement
        ));
    }

    #[test]
    fn dynamic_root_aarch64_target_receipts_follow_linux_mixed_policy() {
        let filter = dynamic_root_test_filter(b"AC", 3);
        let sve = FeatureSet::of(CpuFeature::Aarch64Sve);
        let sve2 = sve.with(CpuFeature::Aarch64Sve2);
        let asimd = FeatureSet::of(CpuFeature::Aarch64Asimd);
        let cases = [
            (
                Target::aarch64_linux(),
                NativeScannerIsa::Aarch64ScalarRange,
                StartAccelerator::Scalar,
            ),
            (
                Target::aarch64_macos().with_features(sve2).unwrap(),
                NativeScannerIsa::Aarch64ScalarRange,
                StartAccelerator::Scalar,
            ),
            (
                Target::aarch64_macos().with_features(asimd).unwrap(),
                NativeScannerIsa::Aarch64Asimd,
                StartAccelerator::Aarch64Asimd,
            ),
            (
                Target::aarch64_linux().with_features(sve).unwrap(),
                NativeScannerIsa::Aarch64Sve,
                StartAccelerator::Aarch64Sve,
            ),
            (
                Target::aarch64_linux().with_features(sve2).unwrap(),
                NativeScannerIsa::Aarch64Sve2,
                StartAccelerator::Aarch64Sve2,
            ),
            (
                Target::aarch64_linux()
                    .with_features(asimd.with(CpuFeature::Aarch64Sve))
                    .unwrap(),
                NativeScannerIsa::Aarch64Sve,
                StartAccelerator::Aarch64Sve,
            ),
            (
                Target::aarch64_linux()
                    .with_features(asimd.with(CpuFeature::Aarch64Sve).with(CpuFeature::Aarch64Sve2))
                    .unwrap(),
                NativeScannerIsa::Aarch64Sve2,
                StartAccelerator::Aarch64Sve2,
            ),
        ];
        for (target, expected_isa, expected_accelerator) in cases {
            let mut data = vec![0xa5; 32];
            let plan = install_aarch64_dynamic_root_plan(&mut data, 0, filter, target)
                .unwrap_or_else(|error| panic!("dynamic root plan {target:?}: {error}"));
            assert_eq!(plan.scanner.isa, expected_isa, "{target:?}");
            assert_eq!(
                plan.scanner.start_accelerator(),
                expected_accelerator,
                "{target:?}"
            );
            assert!(exact_position_scanner_semantics_are_preserved(
                Some(plan.scanner),
                filter.scan_offset,
                start_filter_membership(filter).unwrap(),
            ));
            assert_eq!(
                plan.use_runtime_vl_dispatch,
                target.operating_system == OperatingSystem::Linux
                    && target.features.has(CpuFeature::Aarch64Asimd)
                    && target.features.has(CpuFeature::Aarch64Sve),
                "{target:?}"
            );
        }
    }

    #[test]
    fn dynamic_root_aarch64_tables_are_post_identity_and_fallback_transactionally() {
        let filter = dynamic_root_test_filter(b"AC", 0);
        let identity = [0x5a; 32];
        let sve2 = FeatureSet::of(CpuFeature::Aarch64Sve)
            .with(CpuFeature::Aarch64Sve2);
        let sve2_target = Target::aarch64_linux().with_features(sve2).unwrap();
        let mut sve2_data = identity.to_vec();
        let sve2_plan = install_aarch64_dynamic_root_plan_with_limit(
            &mut sve2_data,
            0,
            filter,
            sve2_target,
            usize::MAX,
        )
        .unwrap();
        assert_eq!(&sve2_data[..32], &identity);
        assert_eq!(sve2_data.len(), 48);
        assert_eq!(
            sve2_plan.sve_kind,
            Some(Aarch64SveFilterKind::Sve2 {
                match_table_offset: 0,
            })
        );
        assert_eq!(&sve2_data[32..48], b"ACACACACACACACAC");

        let mut fallback_data = identity.to_vec();
        let fallback = install_aarch64_dynamic_root_plan_with_limit(
            &mut fallback_data,
            0,
            filter,
            sve2_target,
            0,
        )
        .unwrap();
        assert_eq!(fallback.sve_kind, Some(Aarch64SveFilterKind::Sve));
        assert_eq!(fallback.scanner.isa, NativeScannerIsa::Aarch64Sve);
        assert_eq!(fallback_data, identity);

        let asimd_target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .unwrap();
        let mut asimd_data = identity.to_vec();
        let asimd = install_aarch64_dynamic_root_plan_with_limit(
            &mut asimd_data,
            0,
            filter,
            asimd_target,
            usize::MAX,
        )
        .unwrap();
        assert_eq!(asimd.lane_index_offset, Some(0));
        assert_eq!(&asimd_data[32..48], &AARCH64_FIRST_LANE_INDEX);

        let mut asimd_fallback_data = identity.to_vec();
        let asimd_fallback = install_aarch64_dynamic_root_plan_with_limit(
            &mut asimd_fallback_data,
            0,
            filter,
            asimd_target,
            0,
        )
        .unwrap();
        assert!(asimd_fallback.use_asimd);
        assert!(!asimd_fallback.use_exact_asimd_lane);
        assert_eq!(asimd_fallback.lane_index_offset, None);
        assert_eq!(asimd_fallback_data, identity);
    }

    #[test]
    fn dynamic_root_aarch64_cfg_prioritizes_root_and_preserves_table_byte_ownership() {
        let filter = dynamic_root_test_filter(b"A", 0);
        let features = FeatureSet::of(CpuFeature::Aarch64Asimd)
            .with(CpuFeature::Aarch64Sve)
            .with(CpuFeature::Aarch64Sve2);
        let target = Target::aarch64_linux().with_features(features).unwrap();
        let mut data = vec![0_u8; 32];
        let plan = install_aarch64_dynamic_root_plan(&mut data, 0, filter, target).unwrap();
        assert!(plan.use_runtime_vl_dispatch);
        let emission = lower_aarch64_dynamic_rows_prepared(Some(plan)).unwrap();
        assert_eq!(emission.scanner, Some(plan.scanner));
        assert_eq!(
            emission
                .relocations
                .iter()
                .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL)
                .count(),
            1,
            "root-scanner AArch64 entry continues exact holes"
        );
        let words = emission
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let scanner_free_ceiling = aarch64_cmp_x_imm(
            8,
            u16::try_from(FROZEN_SCANNER_FREE_DYNAMIC_ROWS_MAX_INPUT_BYTES).unwrap(),
        )
        .unwrap();
        assert!(
            !words.contains(&scanner_free_ceiling),
            "an installed AArch64 root scanner must retain frozen rows for long windows"
        );
        assert_eq!(
            words
                .iter()
                .filter(|&&word| word == aarch64_sve_cntb(16).unwrap())
                .count(),
            3,
            "mixed dynamic root must restore its VL after both compact loop helpers"
        );
        assert_eq!(
            words
                .iter()
                .filter(|&&word| {
                    word == aarch64_sub_x_imm(17, 16, AARCH64_SVE_MIN_VECTOR_BYTES).unwrap()
                })
                .count(),
            3,
            "mixed dynamic root must restore its VL16 mode after both compact loop helpers"
        );
        assert!(words.contains(&aarch64_mov_x(6, 16).unwrap()));
        assert!(words.contains(&aarch64_sve2_match_b(1, 0, 16).unwrap()));
        assert!(words.contains(&aarch64_cmeq_16b(24, 0, 16).unwrap()));

        let root_compare = words
            .iter()
            .position(|&word| word == aarch64_cmp_w(11, 1).unwrap())
            .expect("initial-row comparison");
        let learned_row_load = words
            .iter()
            .position(|&word| {
                word
                    == aarch64_load_w_imm(
                        8,
                        13,
                        u16::try_from(native_rows_loop_row_offset(0).unwrap()).unwrap(),
                    )
                    .unwrap()
            })
            .expect("learned-row ownership load");
        let table_byte = words
            .windows(3)
            .position(|window| {
                window
                    == [
                        aarch64_load_byte_reg(8, 0, 2).unwrap(),
                        aarch64_load_byte_reg(10, 14, 8).unwrap(),
                        aarch64_add_w_reg(10, 11, 10).unwrap(),
                    ]
            })
            .expect("canonical table byte load");
        let first_consumption = table_byte
            + words[table_byte..]
                .iter()
                .position(|&word| word == aarch64_add_x_imm(2, 2, 1).unwrap())
                .expect("canonical byte consumption");
        assert!(root_compare < learned_row_load);
        assert!(learned_row_load < table_byte);
        assert!(table_byte < first_consumption);

        let scalar = lower_aarch64_dynamic_rows_prepared(None).unwrap();
        assert_eq!(scalar.scanner, None);
        assert_eq!(
            scalar
                .relocations
                .iter()
                .filter(|relocation| relocation.symbol == DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL)
                .count(),
            1
        );
        let scalar_words = scalar
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert_eq!(
            scalar_words
                .iter()
                .filter(|&&word| word == scanner_free_ceiling)
                .count(),
            2,
            "V1/V2 selection and failed/cold preflight retain the scanner-free ceiling"
        );
        assert!(!scalar_words.contains(&aarch64_cmp_w(11, 1).unwrap()));
        assert!(!scalar_words.contains(&aarch64_sve_cntb(16).unwrap()));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one exhaustive test keeps canonical layout and transactional bounds together"
    )]
    fn exact_byte_set_storage_is_canonical_exhaustive_and_transactional() {
        assert!(NativeExactByteSet::from_membership([0; 4], 0, true).is_none());
        assert!(NativeExactByteSet::from_membership([u64::MAX; 4], 0, true).is_none());
        assert_eq!(
            x86_exact_bitmap_displacement(NativeExactByteSetStorage {
                bitmap_offset: u32::try_from(i32::MAX).unwrap(),
                aarch64_lut_offset: None,
                nibble_base: 0,
                sve2_match: None,
            })
            .unwrap(),
            i32::MAX
        );
        assert!(
            x86_exact_bitmap_displacement(NativeExactByteSetStorage {
                bitmap_offset: u32::try_from(i32::MAX).unwrap() + 1,
                aarch64_lut_offset: None,
                nibble_base: 0,
                sve2_match: None,
            })
            .is_err()
        );
        let maximum_nibble_offset = (u32::try_from(i32::MAX).unwrap() - 96) & !31;
        let maximum_nibble_storage = NativeExactByteSetStorage {
            bitmap_offset: 0,
            aarch64_lut_offset: None,
            nibble_base: maximum_nibble_offset,
            sve2_match: None,
        };
        assert_eq!(
            x86_exact_nibble_displacement(maximum_nibble_storage, 3).unwrap(),
            i32::try_from(maximum_nibble_offset + 96).unwrap()
        );
        assert!(x86_exact_nibble_displacement(maximum_nibble_storage, 4).is_err());
        assert!(
            x86_exact_nibble_displacement(
                NativeExactByteSetStorage {
                    nibble_base: 0x8000_0000,
                    ..maximum_nibble_storage
                },
                0
            )
            .is_err()
        );

        for cardinality in 1_u16..=255 {
            let (set, expected) = exact_membership_with_cardinality(cardinality);
            assert_eq!(set.cardinality, cardinality);
            for byte in u8::MIN..=u8::MAX {
                assert_eq!(
                    set.contains(byte),
                    expected[usize::from(byte)],
                    "cardinality={cardinality}, byte={byte}"
                );
            }

            for architecture in [Architecture::X86_64, Architecture::Aarch64] {
                let prefix_len = usize::from(cardinality % 8);
                let prefix = vec![0xa5; prefix_len];
                let mut bytes = prefix.clone();
                let storage = append_native_exact_byte_set(
                    &mut bytes,
                    set,
                    architecture,
                    usize::MAX,
                )
                .expect("exact-set append")
                .expect("exact-set storage");
                assert_eq!(&bytes[..prefix_len], prefix.as_slice());
                assert_eq!(usize::try_from(storage.bitmap_offset).unwrap() % 8, 0);
                assert_eq!(
                    usize::try_from(storage.nibble_base).unwrap()
                        % if architecture == Architecture::X86_64 {
                            32
                        } else {
                            16
                        },
                    0
                );
                let bitmap = usize::try_from(storage.bitmap_offset).unwrap();
                for (index, word) in set.membership.iter().enumerate() {
                    let start = bitmap + index * 8;
                    assert_eq!(&bytes[start..start + 8], &word.to_le_bytes());
                }
                assert_eq!(
                    storage.aarch64_lut_offset.is_some(),
                    architecture == Architecture::Aarch64
                );
                let expected_sve2_match = architecture == Architecture::Aarch64
                    && cardinality.min(256 - cardinality) <= 64;
                assert_eq!(storage.sve2_match.is_some(), expected_sve2_match);
                if let Some(match_storage) = storage.sve2_match {
                    assert_eq!(match_storage.table_base, storage.nibble_base + 48);
                    assert_eq!(
                        usize::from(match_storage.table_count),
                        usize::from(cardinality.min(256 - cardinality)).div_ceil(16)
                    );
                    assert_eq!(match_storage.complement, cardinality > 128);
                }
                let nibble_tables =
                    exact_nibble_tables_from_storage(&bytes, storage, architecture);
                for byte in u8::MIN..=u8::MAX {
                    assert_eq!(
                        exact_storage_contains(&bytes, storage, architecture, byte),
                        expected[usize::from(byte)],
                        "{architecture:?}, cardinality={cardinality}, byte={byte}"
                    );
                    assert_eq!(
                        nibble_tables.contains(byte),
                        expected[usize::from(byte)],
                        "nibble {architecture:?}, cardinality={cardinality}, byte={byte}"
                    );
                    if let Some(match_contains) =
                        exact_sve2_match_contains(&bytes, storage, byte)
                    {
                        assert_eq!(
                            match_contains,
                            expected[usize::from(byte)],
                            "SVE2 MATCH {architecture:?}, cardinality={cardinality}, byte={byte}"
                        );
                    }
                }
            }
        }

        let (set, _) = exact_membership_with_cardinality(64);
        for architecture in [Architecture::X86_64, Architecture::Aarch64] {
            let mut bytes = vec![0x5a; 7];
            let original = bytes.clone();
            let required = if architecture == Architecture::Aarch64 {
                // Bitmap 8..40, scalar LUT 40..296, 8 bytes of alignment,
                // three logical 16-byte nibble tables, and four SVE2 MATCH
                // tables containing the exact 64-byte minority side.
                416
            } else {
                // Bitmap 8..40, 24 bytes of alignment, three duplicated
                // nibble tables and one duplicated low-nibble mask.
                192
            };
            assert_eq!(
                append_native_exact_byte_set(&mut bytes, set, architecture, required - 1)
                    .expect("bounded exact-set append"),
                None
            );
            assert_eq!(bytes, original, "{architecture:?} mutated on decline");
            let installed = append_native_exact_byte_set(
                &mut bytes,
                set,
                architecture,
                required,
            )
            .expect("exact-bound exact-set append")
            .expect("exact-bound exact-set storage");
            assert_eq!(bytes.len(), required);
            assert_eq!(
                exact_nibble_tables_from_storage(&bytes, installed, architecture),
                NativeExactNibbleTables::from_set(set)
            );
        }
    }

    #[test]
    fn exact_scalar_storage_oracle_covers_offsets_tails_and_first_candidate() {
        for cardinality in [1_u16, 2, 63, 64, 65, 127, 128, 129, 191, 255] {
            let (set, expected) = exact_membership_with_cardinality(cardinality);
            for architecture in [Architecture::X86_64, Architecture::Aarch64] {
                let mut bytes = Vec::new();
                let storage = append_native_exact_byte_set(
                    &mut bytes,
                    set,
                    architecture,
                    usize::MAX,
                )
                .unwrap()
                .unwrap();
                for byte in u8::MIN..=u8::MAX {
                    let singleton = [byte];
                    assert_eq!(
                        exact_storage_first_candidate(
                            &bytes,
                            storage,
                            architecture,
                            &singleton,
                            0,
                            1,
                            0,
                        ),
                        expected[usize::from(byte)].then_some(0),
                        "{architecture:?}, cardinality={cardinality}, byte={byte}"
                    );
                }

                let member_bytes = (u8::MIN..=u8::MAX)
                    .filter(|&byte| expected[usize::from(byte)])
                    .take(2)
                    .collect::<Vec<_>>();
                let nonmember = (u8::MIN..=u8::MAX)
                    .find(|&byte| !expected[usize::from(byte)])
                    .unwrap_or(member_bytes[0]);
                for scan_offset in [0_usize, 1, 3, 7, 15] {
                    for tail in 0_usize..=8 {
                        let mut haystack = vec![nonmember; scan_offset + tail];
                        let expected_position = if tail == 0 {
                            None
                        } else {
                            let first = (tail - 1).min(2);
                            haystack[scan_offset + first] = member_bytes[0];
                            if tail > first + 2 {
                                haystack[scan_offset + first + 2] =
                                    *member_bytes.get(1).unwrap_or(&member_bytes[0]);
                            }
                            Some(first)
                        };
                        assert_eq!(
                            exact_storage_first_candidate(
                                &bytes,
                                storage,
                                architecture,
                                &haystack,
                                0,
                                haystack.len(),
                                scan_offset,
                            ),
                            expected_position,
                            "{architecture:?}, cardinality={cardinality}, offset={scan_offset}, tail={tail}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::arithmetic_side_effects,
        reason = "all exhaustive alignment, tail, and lane indices are bounded by their test allocations"
    )]
    fn exact_nibble_classifier_exhausts_cardinalities_alignments_tails_and_first_hits() {
        for cardinality in 1_u16..=255 {
            let (set, expected) = exact_membership_with_cardinality(cardinality);
            let tables = NativeExactNibbleTables::from_set(set);
            let member = (u8::MIN..=u8::MAX)
                .find(|&byte| expected[usize::from(byte)])
                .expect("nonempty exact set");
            let nonmember = (u8::MIN..=u8::MAX)
                .find(|&byte| !expected[usize::from(byte)])
                .expect("nonuniversal exact set");

            for vector_width in [16_usize, 32, 64] {
                for scan_offset in [0_usize, usize::from(cardinality)] {
                    // Every address residue reaches the same first-lane result
                    // through the unaligned vector load.
                    for alignment in 0..vector_width {
                        let lane = (usize::from(cardinality) + alignment) % vector_width;
                        let mut haystack =
                            vec![nonmember; alignment + scan_offset + vector_width + 1];
                        haystack[alignment + scan_offset + lane] = member;
                        assert_eq!(
                            exact_nibble_first_candidate(
                                tables,
                                &haystack,
                                alignment,
                                haystack.len(),
                                scan_offset,
                                vector_width,
                            ),
                            Some(alignment + lane),
                            "cardinality={cardinality}, width={vector_width}, offset={scan_offset}, alignment={alignment}"
                        );
                    }

                    // Exhaust every sub-vector tail and every possible first
                    // hit inside it. A later hit proves lane ordering rather
                    // than mere any-byte membership.
                    for tail in 0..vector_width {
                        let empty = vec![nonmember; scan_offset + tail];
                        assert_eq!(
                            exact_nibble_first_candidate(
                                tables,
                                &empty,
                                0,
                                empty.len(),
                                scan_offset,
                                vector_width,
                            ),
                            None
                        );
                        for first in 0..tail {
                            let mut haystack = vec![nonmember; scan_offset + tail];
                            haystack[scan_offset + first] = member;
                            if first + 1 < tail {
                                haystack[scan_offset + first + 1] = member;
                            }
                            assert_eq!(
                                exact_nibble_first_candidate(
                                    tables,
                                    &haystack,
                                    0,
                                    haystack.len(),
                                    scan_offset,
                                    vector_width,
                                ),
                                Some(first),
                                "cardinality={cardinality}, width={vector_width}, offset={scan_offset}, tail={tail}, first={first}"
                            );
                        }
                    }

                    // Every lane of one complete block is selected exactly,
                    // including the upper AVX2 and AVX-512 lanes.
                    for first in 0..vector_width {
                        let mut haystack = vec![nonmember; scan_offset + vector_width];
                        haystack[scan_offset + first] = member;
                        if first + 1 < vector_width {
                            haystack[scan_offset + first + 1] = member;
                        }
                        assert_eq!(
                            exact_nibble_first_candidate(
                                tables,
                                &haystack,
                                0,
                                haystack.len(),
                                scan_offset,
                                vector_width,
                            ),
                            Some(first),
                            "cardinality={cardinality}, width={vector_width}, offset={scan_offset}, first={first}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_lines,
        reason = "all scalable VL, alignment, tail, and lane indices are bounded by test allocations"
    )]
    fn exact_sve_models_exhaust_scalable_lengths_predicated_tails_and_first_hits() {
        for cardinality in [64_u16, 65, 192] {
            let (set, expected) = exact_membership_with_cardinality(cardinality);
            let tables = NativeExactNibbleTables::from_set(set);
            let mut bytes = Vec::new();
            let storage = append_native_exact_byte_set(
                &mut bytes,
                set,
                Architecture::Aarch64,
                usize::MAX,
            )
            .unwrap()
            .unwrap();
            let mut kinds = vec![Aarch64ExactSveKind::Nibble];
            if let Some(match_storage) = storage.sve2_match {
                kinds.push(Aarch64ExactSveKind::Sve2Match(match_storage));
            }
            let member = (u8::MIN..=u8::MAX)
                .find(|&byte| expected[usize::from(byte)])
                .expect("nonempty exact set");
            let nonmember = (u8::MIN..=u8::MAX)
                .find(|&byte| !expected[usize::from(byte)])
                .expect("nonuniversal exact set");

            for kind in kinds {
                for vector_length in (16_usize..=256).step_by(16) {
                    for scan_offset in [0_usize, 255] {
                        // Every unaligned start residue selects the same lane,
                        // including hits after one completely rejected vector.
                        for alignment in 0..vector_length {
                            let lane = (usize::from(cardinality) + alignment) % vector_length;
                            let expected_position = alignment + vector_length + lane;
                            let mut haystack = vec![
                                nonmember;
                                scan_offset + expected_position + vector_length + 1
                            ];
                            haystack[scan_offset + expected_position] = member;
                            assert_eq!(
                                exact_sve_first_candidate(
                                    &bytes,
                                    storage,
                                    tables,
                                    kind,
                                    &haystack,
                                    alignment,
                                    haystack.len(),
                                    scan_offset,
                                    vector_length,
                                ),
                                Some(expected_position),
                                "cardinality={cardinality}, kind={kind:?}, VL={vector_length}, offset={scan_offset}, alignment={alignment}"
                            );
                        }

                        // Exhaust every architectural tail length and every
                        // possible first active hit. A second adjacent member
                        // proves that first-lane selection remains ordered.
                        for tail in 0..=vector_length {
                            let empty = vec![nonmember; scan_offset + tail];
                            assert_eq!(
                                exact_sve_first_candidate(
                                    &bytes,
                                    storage,
                                    tables,
                                    kind,
                                    &empty,
                                    0,
                                    empty.len(),
                                    scan_offset,
                                    vector_length,
                                ),
                                None
                            );
                            for first in 0..tail {
                                let mut haystack = vec![nonmember; scan_offset + tail];
                                haystack[scan_offset + first] = member;
                                if first + 1 < tail {
                                    haystack[scan_offset + first + 1] = member;
                                }
                                assert_eq!(
                                    exact_sve_first_candidate(
                                        &bytes,
                                        storage,
                                        tables,
                                        kind,
                                        &haystack,
                                        0,
                                        haystack.len(),
                                        scan_offset,
                                        vector_length,
                                    ),
                                    Some(first),
                                    "cardinality={cardinality}, kind={kind:?}, VL={vector_length}, offset={scan_offset}, tail={tail}, first={first}"
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one cross-ISA structural test keeps layout, encoding, receipt, and offset assertions together"
    )]
    fn exact_scalar_backends_emit_authenticated_but_unpublishable_receipts() {
        let pattern = r"(?-u:[\x00-\x40])+";
        let compiled = complete_forward_resource_fallback(
            pattern,
            OutputContract::Exists,
            Target::x86_64_linux(),
        );
        let view = compiled
            .program()
            .native_dfa_view()
            .expect("complete retained native view");
        let requirement = view
            .retained_prefix_requirement
            .expect("mandatory exact primary");
        assert_eq!(
            requirement
                .membership
                .iter()
                .map(|word| word.count_ones())
                .sum::<u32>(),
            65
        );

        for architecture in [Architecture::X86_64, Architecture::Aarch64] {
            let (data, layout) = build_native_dfa_table_for_architecture(view, architecture)
                .expect("exact scalar layout");
            assert!(layout.start_filter.is_none());
            let exact = layout.exact_start_byte_set.expect("exact primary IR");
            let storage = layout.exact_start_storage.expect("exact primary storage");
            assert_eq!(exact.membership, requirement.membership);
            assert_eq!(exact.scan_offset, requirement.scan_offset);
            for byte in u8::MIN..=u8::MAX {
                assert_eq!(
                    exact_storage_contains(&data, storage, architecture, byte),
                    exact.contains(byte)
                );
            }

            let (code, receipt) = match architecture {
                Architecture::X86_64 => {
                    let emission =
                        lower_x86_64_dfa_with_emission(layout, FeatureSet::EMPTY).unwrap();
                    assert!(
                        emission
                            .code
                            .windows(4)
                            .filter(|window| *window == [0x49, 0x0f, 0xa3, 0x81])
                            .count()
                            >= 5,
                        "x86 exact scanner lacks unrolled bitmap tests"
                    );
                    (emission.code, emission.scanner)
                }
                Architecture::Aarch64 => {
                    let emission =
                        lower_aarch64_dfa_for_operating_system_with_emission(
                            layout,
                            FeatureSet::EMPTY,
                            OperatingSystem::Linux,
                            None,
                        )
                        .unwrap();
                    let words = emission
                        .code
                        .chunks_exact(4)
                        .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                        .collect::<Vec<_>>();
                    assert!(words.contains(&aarch64_load_byte_reg(8, 6, 8).unwrap()));
                    (emission.code, emission.scanner)
                }
            };
            assert!(!code.is_empty());
            let receipt = receipt.expect("emitted exact primary receipt");
            assert_eq!(receipt.scan_offset, requirement.scan_offset);
            assert_eq!(receipt.membership, requirement.membership);
            assert!(!receipt.vectorized);
            assert!(!retained_prefix_scanner_is_preserved(
                Some(receipt),
                requirement
            ));

            for scan_offset in [0_u8, 1, 31, 127, 255] {
                let varied = NativeDfaLayout {
                    exact_start_byte_set: Some(NativeExactByteSet {
                        scan_offset,
                        ..exact
                    }),
                    ..layout
                };
                let varied_receipt = match architecture {
                    Architecture::X86_64 => {
                        lower_x86_64_dfa_with_emission(varied, FeatureSet::EMPTY)
                            .unwrap()
                            .scanner
                    }
                    Architecture::Aarch64 => {
                        lower_aarch64_dfa_for_operating_system_with_emission(
                            varied,
                            FeatureSet::EMPTY,
                            OperatingSystem::Macos,
                            None,
                        )
                        .unwrap()
                        .scanner
                    }
                }
                .expect("varied exact scanner receipt");
                assert_eq!(varied_receipt.scan_offset, scan_offset);
                assert_eq!(varied_receipt.membership, exact.membership);
                assert!(!varied_receipt.vectorized);
            }
        }
    }

    #[test]
    #[allow(
        clippy::arithmetic_side_effects,
        clippy::too_many_lines,
        reason = "decoded branch bitfields and one cross-ISA receipt remain bounded and auditable"
    )]
    fn exact_avx2_avx512_and_asimd_backends_emit_authenticated_vector_receipts() {
        // A dense arbitrary root set needs the exact nibble scanner, while its
        // singleton complement also admits the independent interior loop
        // skipper. This exercises restoration of the scanner's live tables.
        let pattern = r"(?-u:[^Q])+";
        let compiled = complete_forward_resource_fallback(
            pattern,
            OutputContract::SelectedEnd,
            Target::x86_64_linux(),
        );
        let view = compiled
            .program()
            .native_dfa_view()
            .expect("complete retained native view");
        let requirement = view
            .retained_prefix_requirement
            .expect("mandatory exact primary");

        let (_, x86_layout) =
            build_native_dfa_table_for_architecture(view, Architecture::X86_64).unwrap();
        assert!(x86_layout.loop_skip.is_some());
        let x86 = lower_x86_64_dfa_with_emission(
            x86_layout,
            FeatureSet::of(CpuFeature::X86Avx2),
        )
        .unwrap();
        let x86_receipt = x86.scanner.expect("AVX2 exact scanner receipt");
        assert_eq!(x86_receipt.isa, NativeScannerIsa::X86Avx2);
        assert!(x86_receipt.vectorized);
        assert!(retained_prefix_scanner_is_preserved(
            Some(x86_receipt),
            requirement
        ));
        assert!(
            x86.code
                .windows(4)
                .filter(|window| *window == [0xc4, 0xc1, 0x7e, 0x6f])
                .count()
                >= 8,
            "AVX2 exact scanner did not restore all duplicated nibble constants after loop skip"
        );
        for opcode in [
            [0xc4, 0xe2, 0x75, 0x00, 0xf5].as_slice(),
            [0xc4, 0xe2, 0x6d, 0x00, 0xed].as_slice(),
            [0xc4, 0xe2, 0x65, 0x00, 0xe4].as_slice(),
            [0xc5, 0xfd, 0xd7, 0xc6].as_slice(),
        ] {
            assert!(
                x86.code.windows(opcode.len()).any(|window| window == opcode),
                "AVX2 exact classifier is missing {opcode:02x?}"
            );
        }

        let avx512 = FeatureSet::of(CpuFeature::X86Avx512F)
            .with(CpuFeature::X86Avx512Bw);
        let x86_avx512 = lower_x86_64_dfa_with_emission(x86_layout, avx512).unwrap();
        let avx512_receipt = x86_avx512
            .scanner
            .expect("AVX-512 exact scanner receipt");
        assert_eq!(avx512_receipt.isa, NativeScannerIsa::X86Avx512Bw);
        assert!(avx512_receipt.vectorized);
        assert!(retained_prefix_scanner_is_preserved(
            Some(avx512_receipt),
            requirement
        ));
        assert!(
            x86_avx512
                .code
                .windows(5)
                .filter(|window| *window == [0x62, 0xd2, 0x7d, 0x48, 0x5a])
                .count()
                >= 8,
            "AVX-512 exact scanner did not restore all broadcast nibble constants after loop skip"
        );
        for opcode in [
            [0x62, 0xf2, 0x7e, 0x48, 0x29, 0xd0].as_slice(),
            [0x62, 0xf1, 0x7f, 0x4a, 0x6f, 0xf5].as_slice(),
            [0x62, 0xf2, 0x4d, 0x48, 0x26, 0xce].as_slice(),
            [0xc4, 0xe1, 0xf8, 0x98, 0xc9].as_slice(),
            [0xc4, 0xe1, 0xfb, 0x93, 0xc1].as_slice(),
            [0x48, 0x0f, 0xbc, 0xc0].as_slice(),
        ] {
            assert!(
                x86_avx512
                    .code
                    .windows(opcode.len())
                    .any(|window| window == opcode),
                "AVX-512 exact classifier is missing {opcode:02x?}"
            );
        }

        let (mut aarch64_data, aarch64_layout) =
            build_native_dfa_table_for_architecture(view, Architecture::Aarch64).unwrap();
        assert!(aarch64_layout.loop_skip.is_some());
        let aarch64 = lower_aarch64_dfa_for_operating_system_with_emission(
            aarch64_layout,
            FeatureSet::of(CpuFeature::Aarch64Asimd),
            OperatingSystem::Macos,
            None,
        )
        .unwrap();
        let aarch64_receipt = aarch64.scanner.expect("ASIMD exact scanner receipt");
        assert_eq!(aarch64_receipt.isa, NativeScannerIsa::Aarch64Asimd);
        assert!(aarch64_receipt.vectorized);
        assert!(retained_prefix_scanner_is_preserved(
            Some(aarch64_receipt),
            requirement
        ));
        let words = aarch64
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        for instruction in [
            aarch64_ld1_three_16b(16, 6).unwrap(),
            aarch64_ushr_16b_by_4(20, 0).unwrap(),
            aarch64_tbl1_16b(22, 16, 21).unwrap(),
            aarch64_tbl1_16b(23, 17, 21).unwrap(),
            aarch64_tbl1_16b(20, 18, 20).unwrap(),
            aarch64_cmtst_16b(24, 24, 24).unwrap(),
        ] {
            assert!(
                words.contains(&instruction),
                "ASIMD exact classifier is missing {instruction:#010x}"
            );
        }
        assert!(
            words
                .iter()
                .filter(|&&word| word == aarch64_ld1_three_16b(16, 6).unwrap())
                .count()
                >= 2,
            "ASIMD exact scanner did not restore nibble constants after loop skip"
        );

        let mixed_sve2 = FeatureSet::of(CpuFeature::Aarch64Asimd)
            .with(CpuFeature::Aarch64Sve)
            .with(CpuFeature::Aarch64Sve2);
        let mixed_target = Target::aarch64_linux()
            .with_features(mixed_sve2)
            .unwrap();
        let mut mixed_layout = aarch64_layout;
        let mixed_data_len = aarch64_data.len();
        install_aarch64_sve_loop_storage(
            &mut aarch64_data,
            &mut mixed_layout,
            mixed_target,
        )
        .unwrap();
        let mixed = lower_aarch64_dfa_for_operating_system_with_emission(
            mixed_layout,
            mixed_sve2,
            OperatingSystem::Linux,
            None,
        )
        .unwrap();
        let mixed_receipt = mixed.scanner.expect("mixed SVE2 exact scanner receipt");
        assert_eq!(mixed_receipt.isa, NativeScannerIsa::Aarch64Sve2);
        assert!(retained_prefix_scanner_is_preserved(
            Some(mixed_receipt),
            requirement
        ));
        let mixed_words = mixed
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        let retained_mode = aarch64_sub_x_imm(
            AARCH64_MIXED_ROOT_WIDE_MODE_REGISTER,
            AARCH64_MIXED_ROOT_VL_REGISTER,
            AARCH64_SVE_MIN_VECTOR_BYTES,
        )
        .unwrap();
        assert_eq!(
            mixed_words
                .windows(2)
                .filter(|words| {
                    words[0] == aarch64_sve_cntb(AARCH64_MIXED_ROOT_VL_REGISTER).unwrap()
                        && words[1] == retained_mode
                })
                .count(),
            1,
            "mixed exact scanner must sample the process VL exactly once"
        );
        let mixed_dispatches = mixed_words
            .iter()
            .enumerate()
            .filter_map(|(index, &word)| {
                (word & 0xff00_001f == 0x3400_0011).then_some((index, word))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            mixed_dispatches.len(),
            1,
            "mixed exact scanner must have one VL16 dispatch"
        );
        let (dispatch, branch) = mixed_dispatches[0];
        assert_eq!(
            mixed_words.get(dispatch.checked_add(1).unwrap()),
            Some(&aarch64_sve_ptrue_b()),
            "wide mixed exact VL must fall through to SVE2"
        );
        let immediate = (((branch >> 5) & 0x7_ffff) << 13).cast_signed() >> 13;
        let asimd_target = usize::try_from(
            i32::try_from(dispatch)
                .unwrap()
                .checked_add(immediate)
                .unwrap(),
        )
        .unwrap();
        let asimd_prologue_end = asimd_target
            .checked_add(6)
            .unwrap()
            .min(mixed_words.len());
        assert!(
            mixed_words[asimd_target..asimd_prologue_end]
                .contains(&aarch64_ld1_three_16b(16, 6).unwrap()),
            "VL16 dispatch did not reach the ASIMD exact constant reload"
        );
        assert!(mixed_words.contains(&aarch64_sve2_match_b(1, 0, 16).unwrap()));
        assert!(mixed_words.contains(&aarch64_ld1_three_16b(16, 6).unwrap()));
        assert!(
            mixed_words.contains(&aarch64_sve_cntb(6).unwrap()),
            "independently entered VLA loop did not sample its vector length"
        );
        assert_eq!(
            mixed_words
                .iter()
                .filter(|&&word| word == aarch64_sve_ld1rqb(16, 12).unwrap())
                .count(),
            1,
            "VLA loop must preserve the root SVE2 constant bank"
        );
        assert!(mixed_words.contains(&aarch64_sve_dup_b_imm(24, b'Q').unwrap()));
        assert!(mixed_words.contains(&aarch64_sve_cmpeq_b(1, 0, 24).unwrap()));
        assert!(!mixed_words.contains(&aarch64_sve_ld1rqb(24, 12).unwrap()));
        assert!(!mixed_words.contains(&aarch64_sve2_match_b(1, 0, 24).unwrap()));
        assert_eq!(aarch64_data.len(), mixed_data_len);
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one SVE test keeps base, sparse MATCH, and complement MATCH receipts auditable"
    )]
    fn exact_sve_and_sve2_backends_emit_authenticated_vector_receipts() {
        let sve = FeatureSet::of(CpuFeature::Aarch64Sve);
        let sve2 = sve.with(CpuFeature::Aarch64Sve2);

        let base = complete_forward_resource_fallback(
            r"(?-u:[\x00-\x40])+",
            OutputContract::Exists,
            Target::aarch64_linux().with_features(sve).unwrap(),
        );
        let base_view = base
            .program()
            .native_dfa_view()
            .expect("base-SVE exact native view");
        let base_requirement = base_view
            .retained_prefix_requirement
            .expect("base-SVE exact retained primary");
        let (_, base_layout) =
            build_native_dfa_table_for_architecture(base_view, Architecture::Aarch64).unwrap();
        assert!(
            base_layout
                .exact_start_storage
                .expect("base-SVE exact storage")
                .sve2_match
                .is_none(),
            "65-byte minority must use the fixed-cost nibble route"
        );
        let base_emission = lower_aarch64_dfa_for_operating_system_with_emission(
            base_layout,
            sve,
            OperatingSystem::Linux,
            None,
        )
        .unwrap();
        let base_receipt = base_emission
            .scanner
            .expect("base-SVE exact scanner receipt");
        assert_eq!(base_receipt.isa, NativeScannerIsa::Aarch64Sve);
        assert!(base_receipt.vectorized);
        assert!(retained_prefix_scanner_is_preserved(
            Some(base_receipt),
            base_requirement
        ));
        let base_words = base_emission
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        for instruction in [
            aarch64_sve_ld1rqb(16, 12).unwrap(),
            aarch64_sve_ld1rqb(17, 12).unwrap(),
            aarch64_sve_ld1rqb(18, 12).unwrap(),
            aarch64_sve_lsr_b_by_4(4, 0).unwrap(),
            aarch64_sve_tbl_b(6, 16, 5).unwrap(),
            aarch64_sve_tbl_b(7, 17, 5).unwrap(),
            aarch64_sve_tbl_b(4, 18, 4).unwrap(),
            aarch64_sve_cmpne_zero_b(1, 6).unwrap(),
            aarch64_sve_whilelo_b(0, 2, 3).unwrap(),
            aarch64_sve_addvl(2, 2, 1).unwrap(),
        ] {
            assert!(
                base_words.contains(&instruction),
                "base-SVE exact classifier is missing {instruction:#010x}"
            );
        }
        assert!(!base_words.contains(&aarch64_sve2_match_b(1, 0, 16).unwrap()));

        let mixed_sve = FeatureSet::of(CpuFeature::Aarch64Asimd)
            .with(CpuFeature::Aarch64Sve);
        let mixed_base = lower_aarch64_dfa_for_operating_system_with_emission(
            base_layout,
            mixed_sve,
            OperatingSystem::Linux,
            None,
        )
        .unwrap();
        let mixed_base_receipt = mixed_base
            .scanner
            .expect("mixed base-SVE exact scanner receipt");
        assert_eq!(mixed_base_receipt.isa, NativeScannerIsa::Aarch64Sve);
        assert!(retained_prefix_scanner_is_preserved(
            Some(mixed_base_receipt),
            base_requirement
        ));
        let mixed_base_words = mixed_base
            .code
            .chunks_exact(4)
            .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
            .collect::<Vec<_>>();
        assert!(mixed_base_words.contains(&aarch64_sve_tbl_b(6, 16, 5).unwrap()));
        assert!(mixed_base_words.contains(&aarch64_ld1_three_16b(16, 6).unwrap()));
        assert!(
            mixed_base_words
                .iter()
                .any(|word| word & 0xff00_001f == 0x3400_0011),
            "mixed base-SVE exact scanner must retain its VL16 ASIMD arm"
        );

        for (pattern, cardinality, table_count, complement) in [
            (r"(?-u:[ACEGIKMOQ])+", 9_u32, 1_u8, false),
            (r"(?-u:[ACEGIKMOQSUWYaceg])+", 17, 2, false),
            (r"(?-u:[^ACEGIKMOQ])+", 247, 1, true),
        ] {
            let compiled = complete_forward_resource_fallback(
                pattern,
                OutputContract::SelectedEnd,
                Target::aarch64_linux().with_features(sve2).unwrap(),
            );
            let view = compiled
                .program()
                .native_dfa_view()
                .expect("SVE2 exact native view");
            let requirement = view
                .retained_prefix_requirement
                .expect("SVE2 exact retained primary");
            assert_eq!(
                requirement
                    .membership
                    .iter()
                    .map(|word| word.count_ones())
                    .sum::<u32>(),
                cardinality
            );
            let (_, layout) =
                build_native_dfa_table_for_architecture(view, Architecture::Aarch64).unwrap();
            let match_storage = layout
                .exact_start_storage
                .expect("SVE2 exact storage")
                .sve2_match
                .expect("SVE2 minority tables");
            assert_eq!(match_storage.table_count, table_count);
            assert_eq!(match_storage.complement, complement);
            let emission = lower_aarch64_dfa_for_operating_system_with_emission(
                layout,
                sve2,
                OperatingSystem::Linux,
                None,
            )
            .unwrap();
            let receipt = emission.scanner.expect("SVE2 exact scanner receipt");
            assert_eq!(receipt.isa, NativeScannerIsa::Aarch64Sve2);
            assert!(receipt.vectorized);
            assert!(retained_prefix_scanner_is_preserved(
                Some(receipt),
                requirement
            ));
            let words = emission
                .code
                .chunks_exact(4)
                .map(|bytes| u32::from_le_bytes(bytes.try_into().unwrap()))
                .collect::<Vec<_>>();
            assert!(words.contains(&aarch64_sve_ld1rqb(16, 12).unwrap()));
            assert!(words.contains(&aarch64_sve2_match_b(1, 0, 16).unwrap()));
            assert_eq!(
                words.contains(&aarch64_sve2_match_b(2, 0, 17).unwrap()),
                table_count > 1
            );
            assert_eq!(
                words.contains(&aarch64_sve_orr_b(1, 1, 2).unwrap()),
                table_count > 1
            );
            assert_eq!(
                words.contains(&aarch64_sve_not_b(1, 1).unwrap()),
                complement
            );
            assert!(!words.contains(&aarch64_sve_tbl_b(6, 16, 5).unwrap()));
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one encoding test keeps AVX2, AVX-512, and ASIMD displacement shapes together"
    )]
    fn exact_nibble_vector_helpers_have_exact_encodings_and_displacement_boundaries() {
        let cases = [
            (0_u8, vec![0xc5, 0xfe, 0x6f, 0x04, 0x17]),
            (127, vec![0xc5, 0xfe, 0x6f, 0x44, 0x17, 0x7f]),
            (
                128,
                vec![0xc5, 0xfe, 0x6f, 0x84, 0x17, 0x80, 0x00, 0x00, 0x00],
            ),
            (
                255,
                vec![0xc5, 0xfe, 0x6f, 0x84, 0x17, 0xff, 0x00, 0x00, 0x00],
            ),
        ];
        for (scan_offset, expected) in cases {
            let mut assembler = X86Assembler::new();
            x86_emit_start_filter_vector_load(
                &mut assembler,
                X86StartFilterKind::Avx2,
                scan_offset,
            )
            .unwrap();
            assert_eq!(assembler.finish().unwrap(), expected);
        }

        let avx512_cases = [
            (0_u8, vec![0x62, 0xf1, 0x7f, 0x48, 0x6f, 0x04, 0x17]),
            (
                127,
                vec![
                    0x62, 0xf1, 0x7f, 0x48, 0x6f, 0x84, 0x17, 0x7f, 0x00, 0x00, 0x00,
                ],
            ),
            (
                128,
                vec![
                    0x62, 0xf1, 0x7f, 0x48, 0x6f, 0x84, 0x17, 0x80, 0x00, 0x00, 0x00,
                ],
            ),
            (
                255,
                vec![
                    0x62, 0xf1, 0x7f, 0x48, 0x6f, 0x84, 0x17, 0xff, 0x00, 0x00, 0x00,
                ],
            ),
        ];
        for (scan_offset, expected) in avx512_cases {
            let mut assembler = X86Assembler::new();
            x86_emit_start_filter_vector_load(
                &mut assembler,
                X86StartFilterKind::Avx512Bw,
                scan_offset,
            )
            .unwrap();
            assert_eq!(assembler.finish().unwrap(), expected);
        }

        let storage = NativeExactByteSetStorage {
            bitmap_offset: 0,
            aarch64_lut_offset: None,
            nibble_base: 32,
            sve2_match: None,
        };
        let mut assembler = X86Assembler::new();
        x86_emit_exact_avx512_constants(&mut assembler, storage).unwrap();
        assert_eq!(
            assembler.finish().unwrap(),
            [
                0x62, 0xd2, 0x7d, 0x48, 0x5a, 0x89, 0x20, 0x00, 0x00, 0x00, 0x62, 0xd2,
                0x7d, 0x48, 0x5a, 0x91, 0x40, 0x00, 0x00, 0x00, 0x62, 0xd2, 0x7d, 0x48,
                0x5a, 0x99, 0x60, 0x00, 0x00, 0x00, 0x62, 0xd2, 0x7d, 0x48, 0x5a, 0xb9,
                0x80, 0x00, 0x00, 0x00,
            ]
        );
        let mut assembler = X86Assembler::new();
        x86_emit_exact_avx512_candidates(&mut assembler, 0).unwrap();
        let avx512_candidates = assembler.finish().unwrap();
        // Independently assembled with AVX-512F+BW and without AVX-512VL.
        for instruction in [
            [0x62, 0xf1, 0x7f, 0x48, 0x6f, 0x04, 0x17].as_slice(),
            [0x62, 0xf1, 0x5d, 0x48, 0x71, 0xd0, 0x04].as_slice(),
            [0x62, 0xf2, 0x75, 0x48, 0x00, 0xf5].as_slice(),
            [0x62, 0xf2, 0x7e, 0x48, 0x29, 0xd0].as_slice(),
            [0x62, 0xf1, 0x7f, 0x4a, 0x6f, 0xf5].as_slice(),
            [0x62, 0xf2, 0x4d, 0x48, 0x26, 0xce].as_slice(),
        ] {
            assert!(
                avx512_candidates
                    .windows(instruction.len())
                    .any(|window| window == instruction),
                "AVX-512 exact helper is missing {instruction:02x?}"
            );
        }

        assert_eq!(aarch64_ld1_three_16b(16, 6).unwrap(), 0x4c40_60d0);
        assert_eq!(aarch64_ushr_16b_by_4(20, 0).unwrap(), 0x6f0c_0414);
        assert_eq!(aarch64_tbl1_16b(22, 16, 21).unwrap(), 0x4e15_0216);
        assert_eq!(aarch64_tbl1_16b(23, 17, 21).unwrap(), 0x4e15_0237);
        assert_eq!(aarch64_cmlt_zero_16b(24, 0).unwrap(), 0x4e20_a818);
        assert_eq!(aarch64_bsl_16b(24, 23, 22).unwrap(), 0x6e76_1ef8);
        assert_eq!(aarch64_tbl1_16b(20, 18, 20).unwrap(), 0x4e14_0254);
        assert_eq!(aarch64_cmtst_16b(24, 24, 24).unwrap(), 0x4e38_8f18);
        assert!(aarch64_ld1_three_16b(30, 6).is_err());

        // Independently assembled with the base-SVE and SVE2 architectural
        // feature sets. The arbitrary-set nibble route uses only base SVE;
        // MATCH and predicate inversion are the authenticated SVE2 route.
        assert_eq!(aarch64_sve_tbl_b(4, 16, 5).unwrap(), 0x0525_3204);
        assert_eq!(aarch64_sve_lsr_b_by_4(5, 0).unwrap(), 0x042c_9405);
        assert_eq!(aarch64_sve_and_z(6, 0, 19).unwrap(), 0x0433_3006);
        assert_eq!(aarch64_sve_cmplt_zero_b(1, 0).unwrap(), 0x2500_2001);
        assert_eq!(aarch64_sve_sel_b(7, 1, 17, 16).unwrap(), 0x0530_c627);
        assert_eq!(aarch64_sve_cmpne_zero_b(2, 7).unwrap(), 0x2500_80f2);
        assert_eq!(aarch64_sve_not_b(1, 1).unwrap(), 0x2500_4221);
        assert!(aarch64_sve_cmplt_zero_b(16, 0).is_err());
        assert!(aarch64_sve_sel_b(0, 16, 0, 0).is_err());
        assert!(aarch64_sve_cmpne_zero_b(16, 0).is_err());
        assert!(aarch64_sve_not_b(0, 16).is_err());
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one publication matrix keeps every output, target, relocation, and receipt together"
    )]
    fn exact_vector_publication_covers_all_outputs_and_supported_operating_systems() {
        let targets = [
            (
                Target::x86_64_linux()
                    .with_features(FeatureSet::of(CpuFeature::X86Avx2))
                    .unwrap(),
                StartAccelerator::X86Avx2,
            ),
            (
                Target::x86_64_macos()
                    .with_features(FeatureSet::of(CpuFeature::X86Avx2))
                    .unwrap(),
                StartAccelerator::X86Avx2,
            ),
            (
                Target::x86_64_linux()
                    .with_features(
                        FeatureSet::of(CpuFeature::X86Avx512F)
                            .with(CpuFeature::X86Avx512Bw),
                    )
                    .unwrap(),
                StartAccelerator::X86Avx512Bw,
            ),
            (
                Target::x86_64_macos()
                    .with_features(
                        FeatureSet::of(CpuFeature::X86Avx512F)
                            .with(CpuFeature::X86Avx512Bw),
                    )
                    .unwrap(),
                StartAccelerator::X86Avx512Bw,
            ),
            (
                Target::aarch64_linux()
                    .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                    .unwrap(),
                StartAccelerator::Aarch64Asimd,
            ),
            (
                Target::aarch64_macos()
                    .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                    .unwrap(),
                StartAccelerator::Aarch64Asimd,
            ),
            (
                Target::aarch64_linux()
                    .with_features(FeatureSet::of(CpuFeature::Aarch64Sve))
                    .unwrap(),
                StartAccelerator::Aarch64Sve,
            ),
            (
                Target::aarch64_linux()
                    .with_features(
                        FeatureSet::of(CpuFeature::Aarch64Sve)
                            .with(CpuFeature::Aarch64Sve2),
                    )
                    .unwrap(),
                // This 65-byte minority exceeds the bounded MATCH cost, so
                // an SVE2-capable target truthfully receipts base SVE.
                StartAccelerator::Aarch64Sve,
            ),
        ];
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let pattern = if output == OutputContract::Span {
                r"(?-u:[\x00-\x40]){17}"
            } else {
                r"(?-u:[\x00-\x40])+"
            };
            for (target, accelerator) in targets {
                let compiled = complete_forward_resource_fallback(pattern, output, target);
                let module = CompiledModule::lower(compiled.program(), target)
                    .expect("ordinary exact retained lowering");
                assert!(
                    module.required_runtime_symbol().is_none(),
                    "{output:?}/{target:?} did not publish its exact vector scanner; accelerator={:?}, reason={:?}, view={:?}",
                    module.start_accelerator(),
                    compiled.receipt().engine_selection_reason,
                    compiled.program().native_dfa_view(),
                );
                assert!(module.required_runtime_symbol().is_none());
                assert!(module.required_runtime_program().is_none());
                assert_eq!(
                    module.start_accelerator(),
                    accelerator,
                    "{output:?}/{target:?}"
                );
                assert!(
                    module.relocations().iter().all(|relocation| {
                        relocation.section == TEXT_SECTION
                            && relocation.symbol == PROGRAM_SYMBOL
                            && usize::try_from(relocation.offset).is_ok_and(|offset| {
                                offset < module.sections()[TEXT_SECTION].bytes().len()
                            })
                    }),
                    "{output:?}/{target:?} emitted an out-of-section or external exact-scanner relocation"
                );
            }
        }

        let sve2_target = Target::aarch64_linux()
            .with_features(
                FeatureSet::of(CpuFeature::Aarch64Sve).with(CpuFeature::Aarch64Sve2),
            )
            .unwrap();
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let pattern = if output == OutputContract::Span {
                r"(?-u:[ACEGIKMOQ]){17}"
            } else {
                r"(?-u:[ACEGIKMOQ])+"
            };
            let compiled = complete_forward_resource_fallback(pattern, output, sve2_target);
            let module = CompiledModule::lower(compiled.program(), sve2_target)
                .expect("ordinary exact SVE2 retained lowering");
            assert!(module.required_runtime_symbol().is_none(), "{output:?}");
            assert!(module.required_runtime_program().is_none());
            assert_eq!(
                module.start_accelerator(),
                StartAccelerator::Aarch64Sve2
            );
            assert!(module.relocations().iter().all(|relocation| {
                relocation.section == TEXT_SECTION
                    && relocation.symbol == PROGRAM_SYMBOL
                    && usize::try_from(relocation.offset).is_ok_and(|offset| {
                        offset < module.sections()[TEXT_SECTION].bytes().len()
                    })
            }));
        }

        // A baseline x86 object and macOS targets without ASIMD still cannot
        // claim an exact vector scanner that their complete retained-table
        // path does not have. The separate dynamic-row fallback can publish
        // the same graph-derived exact set through its scalar scanner.
        for target in [
            Target::x86_64_linux(),
            Target::aarch64_macos()
                .with_features(FeatureSet::of(CpuFeature::Aarch64Sve))
                .unwrap(),
            Target::aarch64_macos()
                .with_features(
                    FeatureSet::of(CpuFeature::Aarch64Sve).with(CpuFeature::Aarch64Sve2),
                )
                .unwrap(),
        ] {
            let compiled = complete_forward_resource_fallback(
                r"(?-u:[\x00-\x40])+",
                OutputContract::Exists,
                target,
            );
            let module = CompiledModule::lower(compiled.program(), target)
                .expect("ordinary scalar exact fallback lowering");
            assert!(module.required_runtime_symbol().is_some(), "{target:?}");
            assert!(module.prepared_entry_symbol().is_some());
            assert_eq!(module.start_accelerator(), StartAccelerator::Scalar);
        }
    }

    #[test]
    fn exact_retained_primary_rebuilds_identically_after_serialization() {
        let target = Target::x86_64_linux();
        let compiled = complete_forward_resource_fallback(
            r"(?-u:[\x00-\x40])+",
            OutputContract::Exists,
            target,
        );
        let wire = compiled.program().serialize().expect("serialize exact primary");
        let restored = crate::CompiledProgram::deserialize(&wire).expect("restore exact primary");
        let original_view = compiled
            .program()
            .native_dfa_view()
            .expect("original exact native view");
        let restored_view = restored
            .native_dfa_view()
            .expect("restored exact native view");
        assert_eq!(
            original_view.retained_prefix_requirement,
            restored_view.retained_prefix_requirement
        );
        for architecture in [Architecture::X86_64, Architecture::Aarch64] {
            let original = build_native_dfa_table_for_architecture(original_view, architecture)
                .expect("original exact layout");
            let rebuilt = build_native_dfa_table_for_architecture(restored_view, architecture)
                .expect("rebuilt exact layout");
            assert_eq!(original, rebuilt, "{architecture:?} exact layout drifted");
        }
        let original_module = CompiledModule::lower(compiled.program(), target)
            .expect("lower original retained exact primary");
        let restored_module = CompiledModule::lower(&restored, target).expect("lower restored");
        assert_eq!(restored_module.sections(), original_module.sections());
        assert_eq!(restored_module.symbols(), original_module.symbols());
        assert_eq!(restored_module.relocations(), original_module.relocations());
        assert_eq!(restored_module.start_accelerator(), StartAccelerator::Scalar);
    }

    #[test]
    fn retained_suffix_requirement_owns_native_primary_selection() {
        let target = Target::x86_64_linux();
        let compiled = complete_forward_resource_fallback(
            "[b-c][a-b]{1,10}xyz",
            OutputContract::Exists,
            target,
        );
        let mut view = compiled
            .program()
            .native_dfa_view()
            .expect("complete retained suffix view");
        let ordinary = derive_suffix_filter(view)
            .unwrap()
            .expect("ordinary suffix selection");
        let mut carried = None;
        for (position, set) in view.anchored_suffix.sets().iter().rev().enumerate() {
            let scan_offset = u8::try_from(position).expect("small anchored suffix");
            if scan_offset != ordinary.filter.scan_offset
                && filter_from_membership_words(set.words(), position, false)
                    .unwrap()
                    .is_some()
            {
                carried = Some((scan_offset, set.words()));
                break;
            }
        }
        let (scan_offset, membership) =
            carried.expect("a second representable terminal column");
        let requirement = view
            .retained_suffix_requirement
            .as_mut()
            .expect("portable retained suffix requirement");
        requirement.scan_offset = scan_offset;
        requirement.membership = membership;

        let (_, layout) = build_native_dfa_table(view).expect("forced retained suffix layout");
        let suffix = layout
            .suffix_filter
            .expect("carried terminal primary survives selection");
        assert_eq!(suffix.filter.scan_offset, scan_offset);
        assert_eq!(start_filter_membership(suffix.filter).unwrap(), membership);
        assert!(
            lower_native_dfa(view, target).unwrap().is_some(),
            "an exact emitted receipt should publish the carried terminal primary"
        );
    }

    #[test]
    fn zero_frontier_suffix_normalization_requires_an_exact_vector_receipt() {
        let targets = [
            Target::x86_64_linux(),
            Target::x86_64_macos(),
            Target::aarch64_linux(),
            Target::aarch64_macos(),
            Target::x86_64_linux()
                .with_features(FeatureSet::of(CpuFeature::X86Avx2))
                .unwrap(),
            Target::x86_64_linux()
                .with_features(
                    FeatureSet::of(CpuFeature::X86Avx512F)
                        .with(CpuFeature::X86Avx512Bw)
                        .with(CpuFeature::X86Avx512Vl),
                )
                .unwrap(),
            Target::aarch64_linux()
                .with_features(
                    FeatureSet::of(CpuFeature::Aarch64Sve)
                        .with(CpuFeature::Aarch64Sve2),
                )
                .unwrap(),
            Target::aarch64_macos()
                .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                .unwrap(),
        ];
        for target in targets {
            let variable_span = complete_forward_resource_fallback(
                "[ab]+",
                OutputContract::Span,
                target,
            );
            assert!(variable_span.program().native_dfa_view().is_none());
            assert!(variable_span.program().native_partial_dfa_view().is_none());
            let variable_materialized = variable_span
                .program()
                .native_fully_prefilled_program()
                .expect("zero-frontier variable Span K0 materialization");
            let variable_view = variable_span
                .program()
                .native_fully_prefilled_view(&variable_materialized);
            let variable_direct = lower_native_dfa(variable_view, target).unwrap().is_some();
            let variable_module = CompiledModule::lower_k0_optimizing_with_data_limit(
                variable_span.program(),
                target,
                usize::MAX,
            )
            .expect("explicit variable-Span K0 lowering");
            assert_eq!(
                variable_module.required_runtime_symbol().is_some(),
                !variable_direct
            );
            assert_eq!(
                variable_module.prepared_entry_symbol().is_some(),
                !variable_direct
                    && variable_span
                        .program()
                        .native_dynamic_rows_view()
                        .is_some(),
                "{target:?}/variable Span dynamic fallback publication"
            );

            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled =
                    complete_forward_resource_fallback("[b-c][a-b]{1,10}z", output, target);
                let direct_view = compiled.program().native_dfa_view();
                assert_eq!(direct_view.is_some(), output != OutputContract::Span);
                let materialized = compiled.program().native_fully_prefilled_program();
                let static_view = materialized
                    .as_ref()
                    .map(|materialized| {
                        compiled
                            .program()
                            .native_fully_prefilled_view(materialized)
                    })
                    .or(direct_view);
                let direct = static_view
                    .is_some_and(|view| lower_native_dfa(view, target).unwrap().is_some());
                let module = CompiledModule::lower_k0_optimizing_with_data_limit(
                    compiled.program(),
                    target,
                    usize::MAX,
                )
                .expect("explicit zero-frontier K0 lowering");
                assert_eq!(module.required_runtime_symbol().is_none(), direct);
                assert!(compiled.program().native_partial_dfa_view().is_none());
                assert_eq!(
                    module.prepared_entry_symbol().is_some(),
                    !direct && compiled.program().native_dynamic_rows_view().is_some(),
                    "{target:?}/{output:?} dynamic fallback publication"
                );
                if direct {
                    let view = static_view.expect("direct complete suffix view");
                    let (_, layout) =
                        build_native_dfa_table_for_architecture(view, target.architecture)
                            .expect("direct complete suffix layout");
                    assert!(view.partial_discovered_states.is_none());
                    assert!(view.retained_suffix_requirement.is_some());
                    assert!(layout.partial.is_none());
                    assert!(layout.suffix_filter.is_some());
                    assert!(layout.prefix_fast_forward.is_some());
                    assert!(!matches!(
                        module.start_accelerator(),
                        StartAccelerator::None | StartAccelerator::Scalar
                    ));
                } else if compiled.program().native_dynamic_rows_view().is_some() {
                    let expected = match target.architecture {
                        Architecture::X86_64 => match x86_start_filter_kind(target.features) {
                            X86StartFilterKind::Sse2 => StartAccelerator::X86Sse2,
                            X86StartFilterKind::Avx2 => StartAccelerator::X86Avx2,
                            X86StartFilterKind::Avx512Bw => StartAccelerator::X86Avx512Bw,
                        },
                        Architecture::Aarch64
                            if target.operating_system == OperatingSystem::Linux
                                && target.features.has(CpuFeature::Aarch64Sve) =>
                        {
                            // This contiguous root range uses base-SVE
                            // comparisons even on an SVE2 target. Sparse
                            // exact roots exercise SVE2 MATCH elsewhere.
                            StartAccelerator::Aarch64Sve
                        }
                        Architecture::Aarch64
                            if target.features.has(CpuFeature::Aarch64Asimd) =>
                        {
                            StartAccelerator::Aarch64Asimd
                        }
                        Architecture::Aarch64 => StartAccelerator::Scalar,
                    };
                    assert_eq!(
                        module.start_accelerator(),
                        expected,
                        "{target:?}/{output:?} dynamic root scanner receipt"
                    );
                } else {
                    assert_eq!(module.start_accelerator(), StartAccelerator::None);
                }
            }

            // The complete retained-table path still requires an exact vector
            // receipt, but its separate dynamic-row fallback can now scan the
            // same arbitrary graph-derived byte set with a scalar native loop.
            if target.features != FeatureSet::EMPTY {
                continue;
            }
            for pattern in [
                r"(?-u:[\x00-\x40])+",
                r"(?-u:[\x00\x20\x40\x60\x80\xa0\xc0\xe0\xff])+",
            ] {
                let prefix_accelerated = complete_forward_resource_fallback(
                    pattern,
                    OutputContract::Exists,
                    target,
                );
                let module = CompiledModule::lower(prefix_accelerated.program(), target)
                    .expect("ordinary exact prepared fallback lowering");
                assert!(
                    module.required_runtime_symbol().is_some(),
                    "{pattern:?}/{target:?} discarded the prepared fallback workspace"
                );
                assert!(module.prepared_entry_symbol().is_some());
                assert_eq!(module.start_accelerator(), StartAccelerator::Scalar);
            }
        }

        let target = Target::x86_64_linux();
        let nullable_span = complete_forward_resource_fallback(
            "[ab]*",
            OutputContract::Span,
            target,
        );
        let nullable_view = nullable_span
            .program()
            .native_dfa_view()
            .expect("initial-pending complete retained Span view");
        let (_, nullable_layout) =
            build_native_dfa_table(nullable_view).expect("initial-pending Span layout");
        assert!(nullable_view.dfa.initial_pending);
        assert_eq!(nullable_view.exact_match_width, None);
        assert!(nullable_view.partial_discovered_states.is_none());
        assert!(nullable_view.retained_suffix_requirement.is_none());
        assert!(!nullable_layout.has_reverse);
        let nullable_module = CompiledModule::lower(nullable_span.program(), target)
            .expect("ordinary nullable retained lowering");
        assert!(nullable_module.required_runtime_symbol().is_none());
        assert!(nullable_span.program().native_partial_dfa_view().is_none());
        assert!(nullable_module.prepared_entry_symbol().is_none());

        let exact_span = complete_forward_resource_fallback(
            "(?:ab|cd)z",
            OutputContract::Span,
            target,
        );
        let exact_view = exact_span
            .program()
            .native_dfa_view()
            .expect("fixed-width complete retained Span view");
        let (_, exact_layout) =
            build_native_dfa_table(exact_view).expect("fixed-width Span layout");
        assert!(!exact_view.dfa.initial_pending);
        assert_eq!(exact_view.exact_match_width, Some(3));
        assert!(exact_view.partial_discovered_states.is_none());
        assert!(exact_view.retained_suffix_requirement.is_none());
        assert_eq!(exact_layout.exact_span_width, Some(3));
        assert!(!exact_layout.has_reverse);
        let exact_module = CompiledModule::lower(exact_span.program(), target)
            .expect("ordinary exact-width retained lowering");
        assert!(exact_module.required_runtime_symbol().is_none());
        assert!(exact_span.program().native_partial_dfa_view().is_none());
        assert!(exact_module.prepared_entry_symbol().is_none());

        let cut = complete_forward_resource_fallback(
            "[b-c][a-b]{1,10}7[A-Za-z]{1,2}",
            OutputContract::Exists,
            target,
        );
        assert!(cut.program().native_dfa_view().is_none());
        assert!(cut.program().native_partial_dfa_view().is_none());
        assert!(cut.program().native_dynamic_rows_view().is_some());
        let cut_module = CompiledModule::lower(cut.program(), target)
            .expect("ordinary mandatory-cut fallback lowering");
        assert!(cut_module.required_runtime_symbol().is_some());
        assert!(cut_module.prepared_entry_symbol().is_some());
        assert_eq!(
            cut_module.required_prepared_preflight_runtime_symbol(),
            Some(DYNAMIC_ROWS_PREFLIGHT_RUNTIME_SYMBOL_NAME)
        );
        assert_eq!(
            cut_module.required_prepared_dynamic_rows_deopt_runtime_symbol(),
            Some(DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL_NAME)
        );

        let compiled = complete_forward_resource_fallback(
            "[b-c][a-b]{1,10}z",
            OutputContract::Exists,
            target,
        );
        let wire = compiled.program().serialize().expect("serialize suffix");
        let restored = crate::CompiledProgram::deserialize(&wire).expect("restore suffix");
        assert_eq!(
            restored
                .native_dfa_view()
                .and_then(|view| view.retained_suffix_requirement),
            compiled
                .program()
                .native_dfa_view()
                .and_then(|view| view.retained_suffix_requirement)
        );
        let original_module = CompiledModule::lower(compiled.program(), target)
            .expect("lower original suffix");
        let restored_module = CompiledModule::lower(&restored, target).expect("lower restored");
        assert_eq!(restored_module.sections(), original_module.sections());
        assert_eq!(restored_module.symbols(), original_module.symbols());
        assert_eq!(restored_module.relocations(), original_module.relocations());

        let mut mismatched = compiled
            .program()
            .native_dfa_view()
            .expect("complete suffix view");
        mismatched
            .retained_suffix_requirement
            .as_mut()
            .expect("suffix requirement")
            .membership[0] ^= 1;
        assert!(lower_native_dfa(mismatched, target).unwrap().is_none());

        let mut mismatched = compiled
            .program()
            .native_dfa_view()
            .expect("complete suffix view");
        let requirement = mismatched
            .retained_suffix_requirement
            .as_mut()
            .expect("suffix requirement");
        requirement.scan_offset = requirement
            .scan_offset
            .checked_add(1)
            .expect("small suffix scan offset");
        assert!(lower_native_dfa(mismatched, target).unwrap().is_none());

        let mut mismatched = compiled
            .program()
            .native_dfa_view()
            .expect("complete suffix view");
        let requirement = mismatched
            .retained_suffix_requirement
            .as_mut()
            .expect("suffix requirement");
        requirement.minimum_width = requirement
            .minimum_width
            .checked_add(1)
            .expect("small suffix minimum width");
        assert!(lower_native_dfa(mismatched, target).unwrap().is_none());

        // This view is otherwise directly eligible, but baseline AArch64 has
        // no emitted vector-suffix receipt. The complete static root declines,
        // but Exists can still publish the general warmed-row prepared entry
        // alongside the ordinary runtime adapter.
        let declined_target = Target::aarch64_linux();
        let declined = complete_forward_resource_fallback(
            "[b-c][a-b]{1,10}z",
            OutputContract::Exists,
            declined_target,
        );
        let declined_view = declined
            .program()
            .native_dfa_view()
            .expect("target-independent complete suffix view");
        assert!(lower_native_dfa(declined_view, declined_target)
            .unwrap()
            .is_none());
        let declined_module = CompiledModule::lower(declined.program(), declined_target)
            .expect("ordinary declined retained lowering");
        assert!(declined_module.required_runtime_symbol().is_some());
        assert!(declined_module.prepared_entry_symbol().is_some());
        assert_eq!(
            declined_module.required_prepared_preflight_runtime_symbol(),
            Some(DYNAMIC_ROWS_PREFLIGHT_RUNTIME_SYMBOL_NAME)
        );
        assert_eq!(
            declined_module.required_prepared_dynamic_rows_deopt_runtime_symbol(),
            Some(DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL_NAME)
        );
    }

    #[test]
    fn ordinary_mandatory_cut_publishes_dynamic_rows_on_every_target() {
        let pattern = "[b-c][a-b]{1,10}7[A-Za-z]{1,2}";
        for target in identity_target_matrix() {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled = complete_forward_resource_fallback(pattern, output, target);
                assert!(
                    compiled.program().native_dfa_view().is_none(),
                    "{target:?}/{output:?}"
                );
                assert!(
                    compiled.program().native_partial_dfa_view().is_none(),
                    "{target:?}/{output:?}"
                );
                assert!(
                    !compiled.program().has_nfa_exact_product(),
                    "{target:?}/{output:?}"
                );
                let dynamic = compiled
                    .program()
                    .native_dynamic_rows_view()
                    .unwrap_or_else(|| panic!("missing dynamic cut view: {target:?}/{output:?}"));
                assert!(dynamic.root_requirement.is_some(), "{target:?}/{output:?}");

                let module = CompiledModule::lower(compiled.program(), target)
                    .unwrap_or_else(|error| {
                        panic!("dynamic cut lowering {target:?}/{output:?}: {error}")
                    });
                assert!(
                    module.required_runtime_symbol().is_some(),
                    "{target:?}/{output:?}"
                );
                assert!(
                    module.prepared_entry_symbol().is_some(),
                    "{target:?}/{output:?}"
                );
                assert_eq!(
                    module.required_prepared_preflight_runtime_symbol(),
                    Some(DYNAMIC_ROWS_PREFLIGHT_RUNTIME_SYMBOL_NAME),
                    "{target:?}/{output:?}"
                );
                assert_eq!(
                    module.required_prepared_dynamic_rows_deopt_runtime_symbol(),
                    Some(DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL_NAME),
                    "{target:?}/{output:?}"
                );
                assert_eq!(
                    module.required_prepared_dynamic_rows_continue_runtime_symbol(),
                    Some(DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL_NAME),
                    "root scanner must publish exact first-hole continuation: {target:?}/{output:?}"
                );
                let expected_accelerator = match target.architecture {
                    Architecture::X86_64 => match x86_start_filter_kind(target.features) {
                        X86StartFilterKind::Sse2 => StartAccelerator::X86Sse2,
                        X86StartFilterKind::Avx2 => StartAccelerator::X86Avx2,
                        X86StartFilterKind::Avx512Bw => StartAccelerator::X86Avx512Bw,
                    },
                    Architecture::Aarch64
                        if target.operating_system == OperatingSystem::Linux
                            && target.features.has(CpuFeature::Aarch64Sve) =>
                    {
                        // This contiguous range uses base-SVE comparisons even
                        // when the target also supports SVE2 MATCH. Sparse
                        // exact roots exercise the SVE2 route elsewhere.
                        StartAccelerator::Aarch64Sve
                    }
                    Architecture::Aarch64
                        if target.features.has(CpuFeature::Aarch64Asimd) =>
                    {
                        StartAccelerator::Aarch64Asimd
                    }
                    Architecture::Aarch64 => StartAccelerator::Scalar,
                };
                assert_eq!(
                    module.start_accelerator(),
                    expected_accelerator,
                    "dynamic cut scanner receipt: {target:?}/{output:?}"
                );
            }
        }
    }

    #[test]
    fn complete_retained_nullable_and_fixed_width_spans_match_universal_reference() {
        let target = Target::aarch64_macos();
        let mut cases = vec![(
            "[ab]*",
            generated_byte_strings(b"abx", 5),
        )];
        let fixed_pattern = "[ab]cdefghij(?-u:.){8}";
        let fixed_match = b"acdefghij12345678";
        let mut fixed_sources = vec![
            Vec::new(),
            fixed_match.to_vec(),
            [b"xx".as_slice(), fixed_match, b"yy".as_slice()].concat(),
            b"acdefghij1234567".to_vec(),
            b"xcdefghij12345678".to_vec(),
        ];
        let mut alternate = fixed_match.to_vec();
        alternate[0] = b'b';
        let last = alternate.len() - 1;
        alternate[last] = 0xff;
        fixed_sources.push(alternate);
        cases.push((fixed_pattern, fixed_sources));

        for (pattern, sources) in cases {
            let retained = complete_forward_resource_fallback(
                pattern,
                OutputContract::Span,
                target,
            );
            let reference = compile(
                CompileRequest::new(pattern, target)
                    .mode(CompileMode::Fast)
                    .output(OutputContract::Span),
            )
            .expect("universal reference");
            let mut retained_workspace = retained
                .program()
                .prepare_workspace()
                .expect("retained workspace");
            let mut reference_workspace = reference
                .program()
                .prepare_workspace()
                .expect("reference workspace");
            for source in sources {
                for start in 0..=source.len() {
                    for end in start..=source.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference
                            .program()
                            .search_with_workspace(
                                &source,
                                window,
                                &mut reference_workspace,
                            )
                            .expect("reference search");
                        let actual = retained
                            .program()
                            .search_with_retained_partial_workspace(
                                &source,
                                window,
                                &mut retained_workspace,
                            )
                            .expect("retained complete-forward search");
                        assert_eq!(
                            actual, expected,
                            "{pattern:?} mismatch for {source:?} in {start}..{end}"
                        );
                    }
                }
            }
        }
    }

    #[cfg(all(target_arch = "aarch64", target_os = "macos"))]
    #[test]
    #[ignore = "links and executes complete retained-forward objects natively"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in native differential keeps object production and execution together"
    )]
    fn linked_aarch64_complete_retained_contracts_match_portable_program() {
        use std::{fmt::Write as _, fs, process::Command};

        let target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .expect("ASIMD target");
        let cases = [
            (
                "[ab]+",
                OutputContract::Exists,
                b"xxabbaaxbb".as_slice(),
                None,
            ),
            (
                "[ab]+",
                OutputContract::SelectedEnd,
                b"xxabbaaxbb".as_slice(),
                None,
            ),
            (
                "[ab]*",
                OutputContract::Span,
                b"xxabbaaxbb".as_slice(),
                None,
            ),
            (
                "[ab]cdefghij(?-u:.){8}",
                OutputContract::Span,
                b"xxacdefghij12345678yy".as_slice(),
                None,
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::Exists,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(8),
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::SelectedEnd,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(8),
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::Span,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(8),
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::Exists,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(0),
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::SelectedEnd,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(0),
            ),
            (
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                OutputContract::Span,
                b"!!aaaQ!!cbbbbxxx!!".as_slice(),
                Some(0),
            ),
        ];
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-complete-retained-forward-{}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create linker fixture directory");
        let mut source = String::from("#include <stdint.h>\n#include <stddef.h>\n");
        let mut calls = String::from("int main(void){size_t r[2];uint32_t s;\n");
        let mut objects = Vec::new();

        for (case, (pattern, contract, haystack, materialized_max_states)) in
            cases.iter().enumerate()
        {
            let compiled = if let Some(max_states) = materialized_max_states {
                compile(
                    CompileRequest::new(*pattern, target)
                        .mode(CompileMode::Optimizing)
                        .output(*contract)
                        .limits(CompileLimitsV1 {
                            determinize: DeterminizeLimits {
                                max_states: *max_states,
                                ..DeterminizeLimits::default()
                            },
                            ..CompileLimitsV1::default()
                        }),
                )
                .expect("materialized K0 native differential")
            } else {
                complete_forward_resource_fallback(pattern, *contract, target)
            };
            if let Some(max_states) = materialized_max_states {
                let partial = compiled.program().partial_dfa_stats().unwrap();
                assert_eq!(
                    partial.is_none(),
                    *max_states == 0,
                    "root-only and retained-frontier fixtures must remain distinct"
                );
                if let Some(partial) = partial {
                    assert!(partial.resume_frontiers != 0);
                }
                assert!(compiled.program().native_fully_prefilled_program().is_some());
            }
            assert!(compiled.module().required_runtime_symbol().is_none());
            let bytes = haystack
                .iter()
                .map(std::string::ToString::to_string)
                .collect::<Vec<_>>()
                .join(",");
            writeln!(source, "static const unsigned char h{case}[]={{{bytes}}};")
                .expect("write fixture");
            let symbol = compiled.module().entry_symbol();
            writeln!(
                source,
                "extern uint32_t {symbol}(const unsigned char*,size_t,size_t,size_t,size_t*);"
            )
            .expect("write declaration");
            let object = directory.join(format!("case{case}.o"));
            fs::write(&object, compiled.object()).expect("write native object");
            objects.push(object);

            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let expected = compiled
                        .search(haystack, SearchWindow::new(start, end))
                        .expect("portable expected result");
                    writeln!(
                        calls,
                        "r[0]=99;r[1]=99;s={symbol}(h{case},{},{start},{end},r);",
                        haystack.len()
                    )
                    .expect("write native call");
                    match expected {
                        MatchResult::Exists(found) => writeln!(
                            calls,
                            "if(s!={}||r[0]!=0||r[1]!=0)return {};",
                            u8::from(found),
                            case + 10
                        )
                        .expect("write Exists assertion"),
                        MatchResult::SelectedEnd(Some(match_end)) => writeln!(
                            calls,
                            "if(s!=1||r[0]!={match_end}||r[1]!={match_end})return {};",
                            case + 10
                        )
                        .expect("write SelectedEnd assertion"),
                        MatchResult::Span(Some((match_start, match_end))) => writeln!(
                            calls,
                            "if(s!=1||r[0]!={match_start}||r[1]!={match_end})return {};",
                            case + 10
                        )
                        .expect("write match assertion"),
                        MatchResult::SelectedEnd(None) | MatchResult::Span(None) => writeln!(
                            calls,
                            "if(s!=0||r[0]!=0||r[1]!=0)return {};",
                            case + 10
                        )
                        .expect("write no-match assertion"),
                    }
                }
            }
        }
        calls.push_str("return 0;}\n");
        source.push_str(&calls);
        let c_path = directory.join("complete_retained.c");
        let executable = directory.join("complete_retained");
        fs::write(&c_path, source).expect("write linker harness");
        let status = Command::new("clang")
            .arg("-O0")
            .arg(&c_path)
            .args(&objects)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("invoke clang");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute linked native harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(all(target_arch = "aarch64", target_os = "macos"))]
    #[test]
    #[ignore = "links and executes arbitrary exact-set retained objects natively"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in cross-contract differential keeps object production and execution auditable"
    )]
    fn linked_aarch64_exact_byteset_contracts_match_portable_program() {
        use std::{fmt::Write as _, fs, process::Command};

        let target = Target::aarch64_macos()
            .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
            .expect("ASIMD target");
        let long_selected_end = [
            vec![b'Q'; 40],
            vec![b'!'; 96],
            vec![b'Q'; 2],
        ]
        .concat();
        let cases = [
            (
                r"(?-u:[\x00-\x40])+",
                OutputContract::Exists,
                b"zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz\x20\x21zz".as_slice(),
            ),
            (
                r"(?-u:[^Q])+",
                OutputContract::SelectedEnd,
                long_selected_end.as_slice(),
            ),
            (
                r"(?-u:[\x00-\x40])cdefghij(?-u:.){8}",
                OutputContract::Span,
                b"zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz!cdefghij12345678yy".as_slice(),
            ),
        ];
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-exact-byteset-retained-{}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create exact-set linker fixture directory");
        let mut source = String::from("#include <stdint.h>\n#include <stddef.h>\n");
        let mut calls = String::from("int main(void){size_t r[2];uint32_t s;\n");
        let mut objects = Vec::new();

        for (case, (pattern, contract, haystack)) in cases.iter().enumerate() {
            let compiled = complete_forward_resource_fallback(pattern, *contract, target);
            assert!(compiled.module().required_runtime_symbol().is_none());
            assert_eq!(
                compiled.module().start_accelerator(),
                StartAccelerator::Aarch64Asimd
            );
            let bytes = haystack
                .iter()
                .map(std::string::ToString::to_string)
                .collect::<Vec<_>>()
                .join(",");
            writeln!(source, "static const unsigned char h{case}[]={{{bytes}}};")
                .expect("write exact-set fixture");
            let symbol = compiled.module().entry_symbol();
            writeln!(
                source,
                "extern uint32_t {symbol}(const unsigned char*,size_t,size_t,size_t,size_t*);"
            )
            .expect("write exact-set declaration");
            let object = directory.join(format!("case{case}.o"));
            fs::write(&object, compiled.object()).expect("write exact-set native object");
            objects.push(object);

            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let expected = compiled
                        .search(haystack, SearchWindow::new(start, end))
                        .expect("portable exact-set result");
                    writeln!(
                        calls,
                        "r[0]=99;r[1]=99;s={symbol}(h{case},{},{start},{end},r);",
                        haystack.len()
                    )
                    .expect("write exact-set native call");
                    match expected {
                        MatchResult::Exists(found) => writeln!(
                            calls,
                            "if(s!={}||r[0]!=0||r[1]!=0)return {};",
                            u8::from(found),
                            case + 40
                        )
                        .expect("write Exists assertion"),
                        MatchResult::SelectedEnd(Some(match_end)) => writeln!(
                            calls,
                            "if(s!=1||r[0]!={match_end}||r[1]!={match_end})return {};",
                            case + 40
                        )
                        .expect("write SelectedEnd assertion"),
                        MatchResult::Span(Some((match_start, match_end))) => writeln!(
                            calls,
                            "if(s!=1||r[0]!={match_start}||r[1]!={match_end})return {};",
                            case + 40
                        )
                        .expect("write Span assertion"),
                        MatchResult::SelectedEnd(None) | MatchResult::Span(None) => writeln!(
                            calls,
                            "if(s!=0||r[0]!=0||r[1]!=0)return {};",
                            case + 40
                        )
                        .expect("write no-match assertion"),
                    }
                }
            }
        }
        calls.push_str("return 0;}\n");
        source.push_str(&calls);
        let c_path = directory.join("exact_byteset_retained.c");
        let executable = directory.join("exact_byteset_retained");
        fs::write(&c_path, source).expect("write exact-set linker harness");
        let status = Command::new("clang")
            .arg("-O0")
            .arg(&c_path)
            .args(&objects)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("invoke clang");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute linked exact-set native harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "requires `cargo build -p fre-aot-regex-runtime --lib`; links V6/V7 generated code to the real trusted V2 loop helper"]
    fn linked_host_frozen_loop_v2_matches_real_runtime() {
        use std::{fs, process::Command, time::SystemTime};

        let target = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        let compiled = compile_with_k0_but_without_slow(
            CompileRequest::new(
                r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                target,
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::SelectedEnd)
            .limits(CompileLimitsV1 {
                determinize: DeterminizeLimits {
                    max_states: 0,
                    ..DeterminizeLimits::default()
                },
                ..CompileLimitsV1::default()
            }),
        );
        let mut workspace = compiled.program().prepare_workspace().unwrap();
        let storage = compiled
            .program()
            .compiler_private_frozen_dynamic_rows_storage_v3(
                &mut workspace,
                512 * 1024,
                512 * 1024,
            )
            .expect("linked trusted-loop fixture must retain a compact owner");
        assert!(
            storage.compiler_private_frozen_loop_plan_count() != 0,
            "the linked fixture must publish at least one V6/V7 loop scanner"
        );
        let header = compiled
            .program()
            .compiler_private_frozen_prepared_header_v6(
                &workspace,
                None,
                Some(&storage),
            );
        assert!(header.is_active());
        assert!(header.has_dynamic_rows());

        let module = lower_without_materialized_k0(compiled.program(), target);
        assert_eq!(
            module.required_prepared_dynamic_rows_loop_scan_runtime_symbol(),
            Some("fre_aot_regex_runtime_scan_frozen_loop_v2")
        );
        let entry = module
            .prepared_entry_symbol()
            .expect("trusted-loop prepared entry");
        let (program_symbol, program_len) = module
            .required_runtime_program()
            .expect("trusted-loop runtime program alias");

        let current_exe = std::env::current_exe().expect("current test executable");
        let profile_dir = current_exe
            .parent()
            .and_then(std::path::Path::parent)
            .expect("Cargo profile directory");
        let static_runtime = profile_dir.join("libfre_aot_regex_runtime.a");
        assert!(
            static_runtime.is_file(),
            "build the linked runtime first: cargo build -p fre-aot-regex-runtime --lib ({})",
            static_runtime.display()
        );
        let nonce = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-frozen-loop-v2-{}-{nonce}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create trusted-loop linker directory");
        let object = directory.join("frozen-loop-v2.o");
        fs::write(
            &object,
            crate::emit_object(
                &module,
                ObjectFormat::for_target(target),
                usize::MAX,
            )
            .expect("emit trusted-loop object"),
        )
        .expect("write trusted-loop object");

        // Exercise the V6/V7 capability while live, revoke it through the
        // ordinary runtime, then re-enter generated code through its
        // inactive-capability side exit.
        let source = format!(
            "#include <stddef.h>\n#include <stdint.h>\n#include <string.h>\n\
             typedef void *handle_t;typedef struct{{size_t start;size_t end;}} result_t;\n\
             extern const unsigned char {program_symbol}[];\n\
             extern uint32_t {entry}(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_prepare_exclusive_v1(const unsigned char*,size_t,handle_t*);\n\
             extern uint32_t fre_aot_regex_runtime_search_exclusive_v1(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_destroy_exclusive_v1(handle_t);\n\
             static uint32_t call_native(handle_t h,const unsigned char*p,size_t n,size_t s,size_t e,result_t*r){{\n\
             #if defined(__aarch64__)\n\
               const uintptr_t expected=UINT64_C(0x193857769abcdef0);\n\
               register uintptr_t sentinel __asm__(\"x19\")=expected;\n\
             #elif defined(__x86_64__)\n\
               const uintptr_t expected=UINT64_C(0x123857769abcdef0);\n\
               register uintptr_t sentinel __asm__(\"r12\")=expected;\n\
             #endif\n\
             #if defined(__aarch64__) || defined(__x86_64__)\n\
               __asm__ __volatile__(\"\" : \"+r\"(sentinel));\n\
               uint32_t status={entry}(h,p,n,s,e,r);\n\
               __asm__ __volatile__(\"\" : \"+r\"(sentinel));\n\
               if(sentinel!=expected)return UINT32_C(0xfffffffe);\n\
               return status;\n\
             #else\n\
               return {entry}(h,p,n,s,e,r);\n\
             #endif\n\
             }}\n\
             #define ACTIVE_SEAL UINT64_C({active_seal})\n\
             static unsigned char matching[1025],absent[1025];\n\
             static uint64_t read_u64(handle_t h){{uint64_t v=0;memcpy(&v,h,sizeof(v));return v;}}\n\
             static int prepare(handle_t*h){{return fre_aot_regex_runtime_prepare_exclusive_v1({program_symbol},{program_len}U,h)==0U;}}\n\
             static int destroy(handle_t h){{return fre_aot_regex_runtime_destroy_exclusive_v1(h)==0U;}}\n\
             static int compare(const unsigned char*p,size_t s,size_t e,int base){{\
               handle_t native=0,baseline=0;result_t nr={{91U,92U}},br={{93U,94U}};\
               if(!prepare(&native)||!prepare(&baseline))return base;\
               uint32_t ns=call_native(native,p,sizeof(matching),s,e,&nr);\
               uint32_t bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,p,sizeof(matching),s,e,&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return base+1;\
               if(read_u64(native)!=ACTIVE_SEAL)return base+4;\
               nr.start=95U;nr.end=96U;br.start=97U;br.end=98U;\
               ns=call_native(native,p,sizeof(matching),s,e,&nr);\
               bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,p,sizeof(matching),s,e,&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return base+2;\
               if(read_u64(native)!=ACTIVE_SEAL)return base+5;\
               nr.start=99U;nr.end=100U;br.start=101U;br.end=102U;\
               ns=fre_aot_regex_runtime_search_exclusive_v1(native,p,sizeof(matching),s,e,&nr);\
               bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,p,sizeof(matching),s,e,&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return base+3;\
               nr.start=103U;nr.end=104U;br.start=105U;br.end=106U;\
               ns=call_native(native,p,sizeof(matching),s,e,&nr);\
               bs=fre_aot_regex_runtime_search_exclusive_v1(baseline,p,sizeof(matching),s,e,&br);\
               if(ns!=bs||nr.start!=br.start||nr.end!=br.end)return base+6;\
               if(!destroy(native)||!destroy(baseline))return base+7;return 0;}}\n\
             int main(void){{memset(matching,'a',sizeof(matching));memset(absent,'a',sizeof(absent));\
               matching[sizeof(matching)-1U]='Q';absent[sizeof(absent)-1U]='R';\
               int status=compare(matching,sizeof(matching)-2U,sizeof(matching),1);if(status)return status;\
               status=compare(absent,0U,1U,2);if(status)return status;\
               status=compare(absent,0U,31U,3);if(status)return status;\
               status=compare(matching,0U,sizeof(matching),10);if(status)return status;\
               status=compare(absent,0U,sizeof(absent),20);if(status)return status;\
               return compare(matching,17U,sizeof(matching),30);}}\n",
            active_seal = FROZEN_PREPARED_HEADER_V1_ACTIVE_SEAL,
        );
        let c_path = directory.join("frozen-loop-v2.c");
        let executable = directory.join("frozen-loop-v2");
        fs::write(&c_path, source).expect("write trusted-loop C harness");
        let c_compiler = if cfg!(target_os = "macos") {
            "clang"
        } else {
            "cc"
        };
        let status = Command::new(c_compiler)
            .arg("-O0")
            .arg(&c_path)
            .arg(&object)
            .arg(&static_runtime)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link trusted-loop real-runtime harness");
        assert!(status.success(), "trusted-loop harness failed to link");
        let output = Command::new(&executable)
            .output()
            .expect("execute trusted-loop real-runtime harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        fs::remove_dir_all(&directory).expect("remove trusted-loop linker directory");
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "requires `cargo build -p fre-aot-regex-runtime --lib`; links a zero-row compact Span entry to the real runtime"]
    fn linked_host_zero_row_alternation_span_ignores_false_root_candidates() {
        use std::{fmt::Write as _, fs, process::Command, time::SystemTime};

        let base = if cfg!(target_arch = "x86_64") {
            if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            }
        } else if cfg!(target_os = "linux") {
            Target::aarch64_linux()
        } else {
            Target::aarch64_macos()
        };
        let feature = if cfg!(target_arch = "x86_64") {
            CpuFeature::X86Avx2
        } else {
            CpuFeature::Aarch64Asimd
        };
        let target = base
            .with_features(FeatureSet::of(feature))
            .expect("valid host vector target");
        let mut slow_limits = SlowAotLimits::default();
        slow_limits.determinize.max_states = 0;
        slow_limits.determinize.max_transitions = 0;
        slow_limits.determinize.max_work = 0;
        slow_limits.max_allocation_bytes = 0;
        slow_limits.max_native_data_bytes = 0;
        let compiled = crate::compile_with_slow_aot_limits(
            CompileRequest::new("(?:blphb|betb|gbmmb)Z", target)
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Span)
                .limits(CompileLimitsV1 {
                    determinize: DeterminizeLimits {
                        max_states: 0,
                        ..DeterminizeLimits::default()
                    },
                    ..CompileLimitsV1::default()
                }),
            slow_limits,
        )
        .expect("compile zero-row alternation Span");
        assert_eq!(
            compiled.receipt().engine_selection_reason,
            crate::EngineSelectionReason::DeterminizationResourceLimit,
        );
        let entry = compiled
            .module()
            .prepared_entry_symbol()
            .expect("zero-row alternation prepared entry");
        let (program_symbol, program_len) = compiled
            .module()
            .required_runtime_program()
            .expect("zero-row alternation runtime program");

        let seed = 0x243f_6a88_85a3_08d2_u64;
        let generation_id = 6_usize;
        let safe = b"~!@#%&*+=:;?";
        let candidates = b"bbg";
        let component = |shift: u32| usize::from(((seed >> shift) & 0xffff) as u16);
        let background = |length: usize| {
            (0_usize..length)
                .map(|index| {
                    let safe_index = (index * (13 + component(8) % 16)
                        + generation_id * (11 + component(40) % 16)
                        + component(0))
                        % safe.len();
                    safe[safe_index]
                })
                .collect::<Vec<_>>()
        };
        let phase = (generation_id * (23 + component(20) % 16) + component(16)) % 32;
        let with_fixture = |mut haystack: Vec<u8>| {
            let match_start = (haystack.len() - 5) / 2;
            haystack[match_start..match_start + 5].copy_from_slice(b"betbZ");
            haystack
        };
        let with_roots = |mut haystack: Vec<u8>, limit: usize| {
            for index in (phase..haystack.len().min(limit)).step_by(32) {
                let candidate = (index / 32 + generation_id + component(32)) % candidates.len();
                haystack[index] = candidates[candidate];
            }
            haystack
        };
        let mut one_g_64 = background(64);
        one_g_64[phase] = b'g';
        let mut one_b_64 = background(64);
        one_b_64[phase] = b'b';
        let mut one_g_4096 = background(4096);
        one_g_4096[phase] = b'g';
        let cases = [
            with_fixture(background(64)),
            with_fixture(one_g_64),
            with_fixture(one_b_64),
            with_fixture(with_roots(background(128), 61)),
            with_fixture(background(4096)),
            with_fixture(one_g_4096),
            with_fixture(with_roots(background(4096), 2045)),
            with_fixture(with_roots(background(4096), usize::MAX)),
        ];

        let current_exe = std::env::current_exe().expect("current test executable");
        let profile_dir = current_exe
            .parent()
            .and_then(std::path::Path::parent)
            .expect("Cargo profile directory");
        let static_runtime = profile_dir.join("libfre_aot_regex_runtime.a");
        assert!(
            static_runtime.is_file(),
            "build the linked runtime first: cargo build -p fre-aot-regex-runtime --lib ({})",
            static_runtime.display()
        );
        let nonce = SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .expect("system clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "fre-aot-zero-row-alternation-span-{}-{nonce}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create zero-row linker directory");
        let object = directory.join("zero-row-alternation.o");
        fs::write(&object, compiled.object()).expect("write zero-row object");
        let mut source = format!(
            "#include <stddef.h>\n#include <stdint.h>\n#include <stdio.h>\n\
             typedef void *handle_t;typedef struct{{size_t start;size_t end;}} result_t;\n\
             extern const unsigned char {program_symbol}[];\n\
             extern uint32_t {entry}(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_prepare_exclusive_v1(const unsigned char*,size_t,handle_t*);\n\
             extern uint32_t fre_aot_regex_runtime_search_exclusive_v1(handle_t,const unsigned char*,size_t,size_t,size_t,result_t*);\n\
             extern uint32_t fre_aot_regex_runtime_destroy_exclusive_v1(handle_t);\n\
             static int run(const unsigned char*haystack,size_t length,size_t match_start,int base){{\n\
               handle_t native=0,oracle=0;result_t got={{91U,92U}},expected={{93U,94U}};\n\
               if(fre_aot_regex_runtime_prepare_exclusive_v1({program_symbol},{program_len}U,&native)!=0U)return 10;\n\
               if(fre_aot_regex_runtime_prepare_exclusive_v1({program_symbol},{program_len}U,&oracle)!=0U)return 11;\n\
               uint32_t os=fre_aot_regex_runtime_search_exclusive_v1(oracle,haystack,length,0U,length,&expected);\n\
               uint32_t ns={entry}(native,haystack,length,0U,length,&got);\n\
               if(os!=1U||expected.start!=match_start||expected.end!=match_start+5U)return 12;\n\
               if(ns!=os||got.start!=expected.start||got.end!=expected.end){{fprintf(stderr,\"case=%d native=%u/%zu/%zu oracle=%u/%zu/%zu\\n\",base,ns,got.start,got.end,os,expected.start,expected.end);return base;}}\n\
               if(fre_aot_regex_runtime_destroy_exclusive_v1(native)!=0U)return 14;\n\
               if(fre_aot_regex_runtime_destroy_exclusive_v1(oracle)!=0U)return 15;return 0;}}\n",
        );
        for (index, haystack) in cases.iter().enumerate() {
            let bytes = haystack
                .iter()
                .map(u8::to_string)
                .collect::<Vec<_>>()
                .join(",");
            writeln!(
                source,
                "static const unsigned char haystack{index}[]={{{bytes}}};"
            )
            .expect("write zero-row test haystack");
        }
        source.push_str("int main(void){int status;\n");
        for (index, haystack) in cases.iter().enumerate() {
            let match_start = (haystack.len() - 5) / 2;
            writeln!(
                source,
                "status=run(haystack{index},sizeof(haystack{index}),{match_start}U,{});if(status)return status;",
                40 + index,
            )
            .expect("write zero-row test call");
        }
        source.push_str("return 0;}\n");
        let c_path = directory.join("zero-row-alternation.c");
        let executable = directory.join("zero-row-alternation");
        fs::write(&c_path, source).expect("write zero-row C harness");
        let compiler = if cfg!(target_os = "macos") { "clang" } else { "cc" };
        let status = Command::new(compiler)
            .arg("-O0")
            .arg(&c_path)
            .arg(&object)
            .arg(&static_runtime)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("link zero-row C harness");
        assert!(status.success(), "zero-row C harness failed to link");
        let output = Command::new(&executable)
            .output()
            .expect("execute zero-row C harness");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        fs::remove_dir_all(&directory).expect("remove zero-row linker directory");
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "links and executes a fragmented exact dynamic root on the host ISA"]
    fn linked_host_dynamic_exact_root_entry_preserves_all_outputs_and_windows() {
        #[cfg(target_arch = "x86_64")]
        let (target, expected) = {
            assert!(
                std::is_x86_feature_detected!("avx2"),
                "exact dynamic-root host validation requires AVX2 hardware"
            );
            let base = if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            };
            (
                base.with_features(FeatureSet::of(CpuFeature::X86Avx2))
                    .unwrap(),
                StartAccelerator::X86Avx2,
            )
        };
        #[cfg(target_arch = "aarch64")]
        let (target, expected) = {
            let base = if cfg!(target_os = "linux") {
                Target::aarch64_linux()
            } else {
                Target::aarch64_macos()
            };
            (
                base.with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                    .unwrap(),
                StartAccelerator::Aarch64Asimd,
            )
        };
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            linked_dynamic_rows_entry_for_output(target, expected, output, true);
        }
    }

    #[cfg(all(
        any(target_arch = "x86_64", target_arch = "aarch64"),
        any(target_os = "linux", target_os = "macos")
    ))]
    #[test]
    #[ignore = "links and executes generated no-row exact-product objects natively"]
    #[allow(
        clippy::too_many_lines,
        reason = "the opt-in native differential keeps generated windows and ABI assertions together"
    )]
    fn linked_host_no_row_exact_products_match_fast_program_for_every_window() {
        use std::{fmt::Write as _, fs, process::Command};

        let target = if cfg!(target_arch = "x86_64") {
            let base = if cfg!(target_os = "linux") {
                Target::x86_64_linux()
            } else {
                Target::x86_64_macos()
            };
            // This opt-in linked differential includes fragmented arbitrary
            // byte sets, whose profitable x86 publication tier is AVX2.
            base.with_features(FeatureSet::of(CpuFeature::X86Avx2))
                .expect("host AVX2 target")
        } else {
            let base = if cfg!(target_os = "linux") {
                Target::aarch64_linux()
            } else {
                Target::aarch64_macos()
            };
            base.with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                .expect("host ASIMD target")
        };
        let mut cases = vec![
            ("a", generated_byte_strings(b"ax\xff", 3)),
            ("[ab]x", generated_byte_strings(b"abxy", 3)),
            (
                "(?:ab|cb)(?:d|e)",
                generated_byte_strings(b"abcdex", 3),
            ),
            ("[ab][01]Z", generated_byte_strings(b"ab01Zx", 3)),
            (
                r"(?-u:[ACEGIKMOQ])(?-u:[\x00-\xff])",
                generated_byte_strings(&[b'A', b'C', b'Q', b'x', 0, u8::MAX], 3),
            ),
            (
                r"(?-u:[\x00-\x40])(?-u:[\x80-\xff])",
                generated_byte_strings(&[0, 0x20, 0x40, 0x41, 0x80, 0xff], 3),
            ),
        ];
        let mut width_sixteen = vec![
            Vec::new(),
            b"abcdefghijklmnop".to_vec(),
            b"xabcdefghijklmnopy".to_vec(),
            b"abcdefghijklmnoq".to_vec(),
            b"abcdefghijklmnabcdefghijklmnop".to_vec(),
        ];
        let mut deterministic = (0_u16..=255)
            .map(|byte| u8::try_from((byte * 197 + 31) & 255).unwrap())
            .collect::<Vec<_>>();
        deterministic[117..133].copy_from_slice(b"abcdefghijklmnop");
        width_sixteen.push(deterministic);
        cases.push(("abcdefghijklmnop", width_sixteen));
        let mut width_nine = vec![
            Vec::new(),
            b"\x01abcdefgh".to_vec(),
            b"x\x01abcdefghy".to_vec(),
            b"\x01abcxefgh".to_vec(),
            b"\x01abcdefg\x01abcdefgh".to_vec(),
        ];
        let mut sparse = vec![b'x'; 257];
        sparse[63..72].copy_from_slice(b"\x01abcdefgh");
        sparse[129] = 1;
        sparse[130..138].copy_from_slice(b"abcxefgh");
        width_nine.push(sparse);
        cases.push((r"(?-u:\x01)abcdefgh", width_nine));

        let directory = std::env::temp_dir().join(format!(
            "fre-aot-no-row-exact-product-{}",
            std::process::id()
        ));
        fs::create_dir_all(&directory).expect("create exact-product fixture directory");
        let mut source = String::from("#include <stdint.h>\n#include <stddef.h>\n");
        let mut calls = String::from("int main(void){size_t r[2];uint32_t s;\n");
        let mut objects = Vec::new();
        let mut artifact = 0usize;

        for (pattern, haystacks) in cases {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled = no_row_exact_product_resource_fallback(pattern, output, target);
                assert!(compiled.module().required_runtime_symbol().is_none());
                let reference = compile(
                    CompileRequest::new(pattern, target)
                        .mode(CompileMode::Fast)
                        .output(output),
                )
                .expect("fast ordered-NFA reference");
                let symbol = compiled.module().entry_symbol();
                writeln!(
                    source,
                    "extern uint32_t {symbol}(const unsigned char*,size_t,size_t,size_t,size_t*);"
                )
                .expect("write exact-product declaration");
                let object = directory.join(format!("case{artifact}.o"));
                fs::write(&object, compiled.object()).expect("write exact-product object");
                objects.push(object);

                for (haystack_index, haystack) in haystacks.iter().enumerate() {
                    let bytes = if haystack.is_empty() {
                        "0".to_owned()
                    } else {
                        haystack
                            .iter()
                            .map(std::string::ToString::to_string)
                            .collect::<Vec<_>>()
                            .join(",")
                    };
                    writeln!(
                        source,
                        "static const unsigned char h{artifact}_{haystack_index}[]={{{bytes}}};"
                    )
                    .expect("write exact-product haystack");
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let expected = reference
                                .search(haystack, SearchWindow::new(start, end))
                                .expect("fast expected result");
                            writeln!(
                                calls,
                                "r[0]=99;r[1]=99;s={symbol}(h{artifact}_{haystack_index},{},{start},{end},r);",
                                haystack.len()
                            )
                            .expect("write exact-product native call");
                            let failure = 10 + artifact;
                            match expected {
                                MatchResult::Exists(found) => writeln!(
                                    calls,
                                    "if(s!={}||r[0]!=0||r[1]!=0)return {failure};",
                                    u8::from(found)
                                ),
                                MatchResult::SelectedEnd(Some(match_end)) => writeln!(
                                    calls,
                                    "if(s!=1||r[0]!={match_end}||r[1]!={match_end})return {failure};"
                                ),
                                MatchResult::Span(Some((match_start, match_end))) => writeln!(
                                    calls,
                                    "if(s!=1||r[0]!={match_start}||r[1]!={match_end})return {failure};"
                                ),
                                MatchResult::SelectedEnd(None) | MatchResult::Span(None) => {
                                    writeln!(
                                        calls,
                                        "if(s!=0||r[0]!=0||r[1]!=0)return {failure};"
                                    )
                                }
                            }
                            .expect("write exact-product result assertion");
                        }
                    }
                }
                artifact += 1;
            }
        }
        calls.push_str("return 0;}\n");
        source.push_str(&calls);
        let c_path = directory.join("exact_product.c");
        let executable = directory.join("exact_product");
        fs::write(&c_path, source).expect("write exact-product linker harness");
        let compiler = if cfg!(target_os = "macos") {
            "clang"
        } else {
            "cc"
        };
        let status = Command::new(compiler)
            .arg("-O0")
            .arg(&c_path)
            .args(&objects)
            .arg("-o")
            .arg(&executable)
            .status()
            .expect("invoke host C compiler");
        assert!(status.success());
        let output = Command::new(&executable)
            .output()
            .expect("execute exact-product native differential");
        assert!(
            output.status.success(),
            "status={:?} stdout={} stderr={}",
            output.status.code(),
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the target matrix keeps scanner receipts, private symbols, and relocations in one audit"
    )]
    fn zero_retained_rows_publish_general_dynamic_exists_entry_on_every_target() {
        let limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        for target in identity_target_matrix() {
            let compiled = compile(
                CompileRequest::new("(?:ab|ac)+z", target)
                    .mode(CompileMode::Fast)
                    .output(OutputContract::Exists)
                    .limits(limits),
            )
            .unwrap_or_else(|error| panic!("dynamic zero-row {target:?}: {error}"));
            assert_eq!(compiled.receipt().engine, EngineKind::OrderedNfa);
            assert!(compiled.program().partial_dfa_stats().unwrap().is_none());
            assert!(compiled.program().native_dfa_view().is_none());
            assert!(compiled.program().native_partial_dfa_view().is_none());
            let dynamic_view = compiled
                .program()
                .native_dynamic_rows_view()
                .expect("dynamic graph view");
            assert!(dynamic_view.root_requirement.is_some());
            assert!(compiled.module().prepared_entry_symbol().is_some());
            let expected = match target.architecture {
                Architecture::X86_64 => match x86_start_filter_kind(target.features) {
                    X86StartFilterKind::Sse2 => StartAccelerator::X86Sse2,
                    X86StartFilterKind::Avx2 => StartAccelerator::X86Avx2,
                    X86StartFilterKind::Avx512Bw => StartAccelerator::X86Avx512Bw,
                },
                Architecture::Aarch64
                    if target.operating_system == OperatingSystem::Linux
                        && target.features.has(CpuFeature::Aarch64Sve2) =>
                {
                    StartAccelerator::Aarch64Sve2
                }
                Architecture::Aarch64
                    if target.operating_system == OperatingSystem::Linux
                        && target.features.has(CpuFeature::Aarch64Sve) =>
                {
                    StartAccelerator::Aarch64Sve
                }
                Architecture::Aarch64
                    if target.features.has(CpuFeature::Aarch64Asimd) =>
                {
                    StartAccelerator::Aarch64Asimd
                }
                Architecture::Aarch64 => StartAccelerator::Scalar,
            };
            assert_eq!(
                compiled.module().start_accelerator(),
                expected,
                "dynamic root scanner receipt: {target:?}"
            );
            assert_eq!(
                compiled
                    .module()
                    .required_prepared_preflight_runtime_symbol(),
                Some(DYNAMIC_ROWS_PREFLIGHT_RUNTIME_SYMBOL_NAME)
            );
            assert_eq!(
                compiled.module().required_prepared_fallback_runtime_symbol(),
                Some(PREPARED_FALLBACK_RUNTIME_SYMBOL_NAME)
            );
            assert_eq!(
                compiled
                    .module()
                    .required_prepared_dynamic_rows_deopt_runtime_symbol(),
                Some(DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL_NAME)
            );
            assert_eq!(
                compiled
                    .module()
                    .required_prepared_dynamic_rows_continue_runtime_symbol(),
                Some(DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL_NAME),
                "loop-free root-scanner holes continue exactly: {target:?}"
            );
            assert_eq!(
                compiled.module().symbols()[DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL].name,
                DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL_NAME,
                "{target:?}"
            );
            assert!(
                compiled
                    .module()
                    .required_prepared_span_recovery_runtime_symbol()
                    .is_none()
            );
            assert!(compiled.module().required_prepared_runtime_symbol().is_none());
            assert_eq!(compiled.module().symbols()[PARTIAL_TABLE_SYMBOL].size, 0);
            assert_eq!(
                compiled.module().symbols()[PARTIAL_NATIVE_CORE_SYMBOL].size,
                0
            );
            assert_eq!(
                compiled
                    .module()
                    .relocations()
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == PREPARED_PREFLIGHT_RUNTIME_SYMBOL
                    })
                    .count(),
                1,
                "{target:?}"
            );
            assert_eq!(
                compiled
                    .module()
                    .relocations()
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == DYNAMIC_ROWS_CONTINUE_RUNTIME_SYMBOL
                    })
                    .count(),
                1,
                "{target:?}"
            );
            assert_eq!(
                compiled
                    .module()
                    .relocations()
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == PREPARED_FALLBACK_RUNTIME_SYMBOL
                    })
                    .count(),
                1,
                "{target:?}"
            );
            assert_eq!(
                compiled
                    .module()
                    .relocations()
                    .iter()
                    .filter(|relocation| {
                        relocation.symbol == DYNAMIC_ROWS_DEOPT_RUNTIME_SYMBOL
                    })
                    .count(),
                1,
                "{target:?}"
            );
        }
    }

