    #[test]
    fn selective_incomplete_retained_forward_requires_an_authenticated_target_scanner() {
        let targets = [
            Target::x86_64_linux(),
            Target::x86_64_macos(),
            Target::aarch64_linux(),
            Target::aarch64_macos(),
        ];
        for target in targets {
            let limits = CompileLimitsV1 {
                determinize: DeterminizeLimits {
                    max_states: 8,
                    ..DeterminizeLimits::default()
                },
                ..CompileLimitsV1::default()
            };
            let compiled = compile_with_k0_but_without_slow(
                CompileRequest::new("a+Q|[b-c][a-b]{1,5}(?:x+|y+)", target)
                    .mode(CompileMode::Optimizing)
                    .output(OutputContract::SelectedEnd)
                    .limits(limits),
            );
            let partial = compiled
                .program()
                .partial_dfa_stats()
                .expect("partial-DFA statistics")
                .expect("incomplete retained table");
            assert!(partial.complete_rows < partial.discovered_states);
            assert!(partial.resume_frontiers > 0);
            let materialized = compiled
                .program()
                .native_fully_prefilled_program()
                .expect("complete K0 cache");
            let view = compiled
                .program()
                .native_fully_prefilled_view(&materialized);
            let direct = lower_native_dfa(view, target).unwrap().is_some();
            assert_eq!(compiled.receipt().runtime_helper_required, !direct);
            assert_eq!(compiled.module().required_runtime_symbol().is_some(), !direct);
            assert_eq!(compiled.module().prepared_entry_symbol().is_some(), !direct);
        }
    }

    #[test]
    fn complete_k0_materialization_reuses_every_native_vector_tier_and_preserves_fallback() {
        let limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 8,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        let vector_targets = [
            (
                Target::x86_64_linux()
                    .with_features(FeatureSet::of(CpuFeature::X86Sse2))
                    .unwrap(),
                StartAccelerator::X86Sse2,
            ),
            (
                Target::x86_64_macos()
                    .with_features(FeatureSet::of(CpuFeature::X86Avx2))
                    .unwrap(),
                StartAccelerator::X86Avx2,
            ),
            (
                Target::x86_64_linux()
                    .with_features(
                        FeatureSet::of(CpuFeature::X86Avx512F)
                            .with(CpuFeature::X86Avx512Bw)
                            .with(CpuFeature::X86Avx512Vl),
                    )
                    .unwrap(),
                StartAccelerator::X86Avx512Bw,
            ),
            (
                Target::aarch64_macos()
                    .with_features(FeatureSet::of(CpuFeature::Aarch64Asimd))
                    .unwrap(),
                StartAccelerator::Aarch64Asimd,
            ),
            (
                Target::aarch64_linux()
                    .with_features(FeatureSet::of(CpuFeature::Aarch64Sve))
                    .unwrap(),
                StartAccelerator::Aarch64Sve,
            ),
            (
                Target::aarch64_linux()
                    .with_features(
                        FeatureSet::of(CpuFeature::Aarch64Sve)
                            .with(CpuFeature::Aarch64Sve2),
                    )
                    .unwrap(),
                StartAccelerator::Aarch64Sve,
            ),
        ];

        for (target, accelerator) in vector_targets {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled = compile_with_k0_but_without_slow(
                    CompileRequest::new(
                        "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                        target,
                    )
                    .mode(CompileMode::Optimizing)
                    .output(output)
                    .limits(limits),
                );
                let partial = compiled
                    .program()
                    .partial_dfa_stats()
                    .unwrap()
                    .expect("retained partial statistics");
                assert!(partial.resume_frontiers != 0, "{target:?}/{output:?}");
                assert!(compiled.program().native_dfa_view().is_none());
                assert!(compiled.program().native_exact_product_view().is_none());
                let materialized = compiled
                    .program()
                    .native_fully_prefilled_program()
                    .unwrap_or_else(|| panic!("missing materialized K0: {target:?}/{output:?}"));
                let view = compiled
                    .program()
                    .native_fully_prefilled_view(&materialized);
                let layout = build_native_dfa_table_for_architecture(view, target.architecture)
                    .expect("materialized native table")
                    .1;
                assert_eq!(layout.has_reverse, output == OutputContract::Span);
                assert!(
                    lower_native_dfa(view, target).unwrap().is_some(),
                    "{target:?}/{output:?}"
                );
                assert!(!compiled.receipt().runtime_helper_required);
                assert!(compiled.module().required_runtime_symbol().is_none());
                assert!(compiled.module().prepared_entry_symbol().is_none());
                assert_eq!(compiled.module().start_accelerator(), accelerator);

                let wire = compiled.program().serialize().unwrap();
                let restored = crate::CompiledProgram::deserialize(&wire).unwrap();
                let restored_module = CompiledModule::lower_k0_optimizing_with_data_limit(
                    &restored,
                    target,
                    usize::MAX,
                )
                .unwrap();
                assert_eq!(restored_module.sections(), compiled.module().sections());
                assert_eq!(restored_module.symbols(), compiled.module().symbols());
                assert_eq!(restored_module.relocations(), compiled.module().relocations());
            }
        }

        let root_only_limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        for (target, accelerator) in vector_targets {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let compiled = compile_with_k0_but_without_slow(
                    CompileRequest::new(
                        "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                        target,
                    )
                    .mode(CompileMode::Optimizing)
                    .output(output)
                    .limits(root_only_limits),
                );
                assert!(compiled.program().partial_dfa_stats().unwrap().is_none());
                assert!(compiled.program().native_dfa_view().is_none());
                assert!(compiled.program().native_exact_product_view().is_none());
                assert!(
                    compiled
                        .program()
                        .native_fully_prefilled_program()
                        .is_some(),
                    "{target:?}/{output:?}"
                );
                assert!(!compiled.receipt().runtime_helper_required);
                assert!(compiled.module().required_runtime_symbol().is_none());
                assert!(compiled.module().prepared_entry_symbol().is_none());
                assert_eq!(compiled.module().start_accelerator(), accelerator);

                let wire = compiled.program().serialize().unwrap();
                let restored = crate::CompiledProgram::deserialize(&wire).unwrap();
                let bounded_module = CompiledModule::lower(&restored, target).unwrap();
                if output == OutputContract::Exists {
                    let stats = restored
                        .bit_parallel_exists_stats()
                        .expect("root-only Exists retains the bounded graph executor");
                    assert!(stats.source_nibbles > 1, "{target:?}/{output:?}");
                    assert!(
                        bounded_module.required_runtime_symbol().is_none(),
                        "{target:?}/{output:?}"
                    );
                } else {
                    assert!(
                        bounded_module.required_runtime_symbol().is_some(),
                        "{target:?}/{output:?}"
                    );
                }
                let restored_module = CompiledModule::lower_k0_optimizing_with_data_limit(
                    &restored,
                    target,
                    usize::MAX,
                )
                .unwrap();
                assert_eq!(restored_module.sections(), compiled.module().sections());
                assert_eq!(restored_module.symbols(), compiled.module().symbols());
                assert_eq!(restored_module.relocations(), compiled.module().relocations());
            }
        }

        let sve2_target = Target::aarch64_linux()
            .with_features(
                FeatureSet::of(CpuFeature::Aarch64Sve).with(CpuFeature::Aarch64Sve2),
            )
            .unwrap();
        let sve2 = compile_with_k0_but_without_slow(
            CompileRequest::new(
                r"(?-u:[\x00\x20\x40\x60\x80\xa0\xc0\xe0\xff])+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                sve2_target,
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::SelectedEnd)
            .limits(limits),
        );
        assert!(
            sve2.program()
                .partial_dfa_stats()
                .unwrap()
                .is_some_and(|stats| stats.resume_frontiers != 0)
        );
        assert!(sve2.program().native_fully_prefilled_program().is_some());
        assert!(!sve2.receipt().runtime_helper_required);
        assert_eq!(
            sve2.module().start_accelerator(),
            StartAccelerator::Aarch64Sve2
        );

        let scalar_target = Target::aarch64_linux();
        let scalar = compile_with_k0_but_without_slow(
            CompileRequest::new(
                "a+Q|[b-c][a-b]{1,5}(?:x+|y+)",
                scalar_target,
            )
            .mode(CompileMode::Optimizing)
            .output(OutputContract::Span)
            .limits(limits),
        );
        let materialized = scalar
            .program()
            .native_fully_prefilled_program()
            .expect("target-neutral K0 materialization");
        let view = scalar
            .program()
            .native_fully_prefilled_view(&materialized);
        assert!(lower_native_dfa(view, scalar_target).unwrap().is_none());
        let scalar_program = scalar.program();
        let baseline = CompiledModule::lower_serialized(
            scalar_program.serialize().unwrap(),
            scalar_program
                .native_dfa_view()
                .or_else(|| scalar_program.native_exact_product_view()),
            false,
            scalar_program.native_context_program_view(),
            scalar_program.native_bit_parallel_exists_view(),
            scalar_program.native_partial_dfa_view(),
            scalar_program.native_dynamic_rows_view(),
            scalar_target,
        )
        .unwrap();
        assert_eq!(scalar.module().sections(), baseline.sections());
        assert_eq!(scalar.module().symbols(), baseline.symbols());
        assert_eq!(scalar.module().relocations(), baseline.relocations());
    }

    #[test]
    fn slow_determinization_lowers_a_graph_larger_than_the_k0_cache() {
        let limits = CompileLimitsV1 {
            determinize: DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
            ..CompileLimitsV1::default()
        };
        let compiled = compile(
            CompileRequest::new(r"(?:a|b)*a(?:a|b){15}", Target::x86_64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Exists)
                .limits(limits),
        )
        .expect("slow optimizing compile");

        assert!(compiled.program().native_dfa_view().is_none());
        assert!(compiled.program().native_fully_prefilled_program().is_none());
        let machine = compiled
            .program()
            .native_slow_determinized_program(
                SlowAotLimits::default().determinize,
                SlowAotLimits::default().max_allocation_bytes,
            )
            .unwrap()
            .expect("slow complete DFA");
        assert!(machine.stats().forward_states_before_minimization > 16_385);
        assert!(machine.stats().forward_states < 32);
        assert!(!compiled.receipt().runtime_helper_required);
        assert!(compiled.module().required_runtime_symbol().is_none());
        assert!(compiled.module().prepared_entry_symbol().is_none());

        let fast = compile(
            CompileRequest::new(r"(?:a|b)*a(?:a|b){15}", Target::x86_64_linux())
                .mode(CompileMode::Fast)
                .output(OutputContract::Exists),
        )
        .expect("fast compile");
        assert!(fast.module().required_runtime_symbol().is_some());
        let slow_from_fast =
            CompiledModule::lower_optimizing(fast.program(), Target::x86_64_linux())
                .expect("explicit slow lowering from Fast program");
        assert!(slow_from_fast.required_runtime_symbol().is_none());
        assert!(slow_from_fast.prepared_entry_symbol().is_none());
    }

    fn slow_partial_limits(max_states: usize) -> SlowAotLimits {
        SlowAotLimits {
            determinize: DeterminizeLimits {
                max_states,
                ..DeterminizeLimits::default()
            },
            max_allocation_bytes: 32 * 1024 * 1024,
            max_native_data_bytes: 32 * 1024 * 1024,
        }
    }

    fn slow_forward_minimized_reverse_decline_limits(
        program: &crate::CompiledProgram,
    ) -> SlowAotLimits {
        let defaults = SlowAotLimits::default();
        let complete = program
            .native_slow_determinized_program(
                defaults.determinize,
                defaults.max_allocation_bytes,
            )
            .expect("complete slow minimization oracle")
            .expect("complete slow minimization candidate");
        assert!(complete.report().completed_stages.contains(
            &crate::DeterminizationStage::DfaStateMinimization
        ));
        let mut low = 0_u64;
        let mut high = complete.report().work_completed;
        while low < high {
            let middle = low + (high - low) / 2;
            let stage_completed = program
                .native_slow_determinized_program(
                    DeterminizeLimits {
                        max_work: middle,
                        ..defaults.determinize
                    },
                    defaults.max_allocation_bytes,
                )
                .expect("bounded minimization-stage search")
                .is_some_and(|candidate| {
                    candidate.report().completed_stages.contains(
                        &crate::DeterminizationStage::DfaStateMinimization,
                    )
                });
            if stage_completed {
                high = middle;
            } else {
                low = middle.checked_add(1).expect("bounded minimization midpoint");
            }
        }
        let limits = SlowAotLimits {
            determinize: DeterminizeLimits {
                max_work: low
                    .checked_sub(1)
                    .expect("minimization completion requires work"),
                ..defaults.determinize
            },
            ..defaults
        };
        let retained = program
            .native_slow_determinized_program(
                limits.determinize,
                limits.max_allocation_bytes,
            )
            .expect("forced partial minimization")
            .expect("forced retained minimization candidate");
        assert!(retained.report().decline.as_ref().is_some_and(|decline| {
            decline.stage == crate::DeterminizationStage::DfaStateMinimization
        }));
        assert!(!retained.report().completed_stages.contains(
            &crate::DeterminizationStage::DfaStateMinimization
        ));
        assert!(retained.retained_forward_minimized());
        assert!(retained.stats().reverse_states > 0);
        limits
    }

    fn slow_reverse_decline_limits(program: &crate::CompiledProgram) -> SlowAotLimits {
        let defaults = SlowAotLimits::default();
        let complete = program
            .native_slow_determinized_program(
                defaults.determinize,
                defaults.max_allocation_bytes,
            )
            .expect("complete reverse-stage oracle")
            .expect("complete reverse-stage candidate");
        let mut low = 0_u64;
        let mut high = complete
            .report()
            .work_completed
            .checked_sub(1)
            .expect("reverse construction requires work");
        while low < high {
            let middle = low + (high - low) / 2;
            let owns_complete_forward = program
                .native_slow_determinized_program(
                    DeterminizeLimits {
                        max_work: middle,
                        ..defaults.determinize
                    },
                    defaults.max_allocation_bytes,
                )
                .expect("bounded reverse-stage search")
                .and_then(|candidate| candidate.retained_dimensions())
                .is_some_and(|(rows, discovered)| rows == discovered);
            if owns_complete_forward {
                high = middle;
            } else {
                low = middle.checked_add(1).expect("bounded reverse-stage midpoint");
            }
        }
        let limits = SlowAotLimits {
            determinize: DeterminizeLimits {
                max_work: low,
                ..defaults.determinize
            },
            ..defaults
        };
        let retained = program
            .native_slow_determinized_program(
                limits.determinize,
                limits.max_allocation_bytes,
            )
            .expect("forced reverse-stage decline")
            .expect("forced reverse-stage candidate");
        assert!(retained.report().decline.as_ref().is_some_and(|decline| {
            decline.stage == crate::DeterminizationStage::ReverseSubsetConstruction
        }));
        assert_eq!(retained.stats().reverse_states, 0);
        limits
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one matrix authenticates transient holes, public symbols, and both backends"
    )]
    fn slow_partial_uses_one_whole_search_hole_on_every_target() {
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let fast = compile(
                CompileRequest::new(PARTIAL_LOOP_PATTERN, Target::x86_64_linux())
                    .mode(CompileMode::Fast)
                    .output(output),
            )
            .expect("fast slow-partial fixture");
            let (slow_limits, candidate) = (1..=64)
                .find_map(|max_states| {
                    let limits = slow_partial_limits(max_states);
                    let candidate = fast
                        .program()
                        .native_slow_determinized_program(
                            limits.determinize,
                            limits.max_allocation_bytes,
                        )
                        .expect("bounded slow determinization")?;
                    let (complete, discovered) = candidate.retained_dimensions()?;
                    (complete > 0 && complete < discovered).then_some((limits, candidate))
                })
                .unwrap_or_else(|| panic!("no interior slow prefix for {output:?}"));
            assert!(candidate.is_partial(), "{output:?}");
            let (complete_rows, discovered_states) = candidate
                .retained_dimensions()
                .expect("transient retained dimensions");
            assert!(complete_rows > 0, "{output:?}");
            assert!(complete_rows < discovered_states, "{output:?}");
            let view = fast.program().native_slow_determinized_view(&candidate);
            assert!(view.collapse_partial_holes);
            assert_eq!(view.partial_discovered_states, Some(discovered_states));

            for architecture in [Architecture::X86_64, Architecture::Aarch64] {
                let (_, layout) = build_native_dfa_table_for_architecture(view, architecture)
                    .expect("collapsed slow-partial table");
                let partial = layout.partial.expect("synthetic hole layout");
                assert!(partial.collapse_holes);
                assert_eq!(
                    usize::try_from(partial.resume_states).unwrap(),
                    discovered_states - complete_rows
                );
                let row_bytes = native_row_bytes(
                    layout.transitions,
                    layout.cells,
                    view.dfa.class_count,
                )
                .expect("collapsed slow-partial row geometry");
                let mut saw_hole = false;
                for &cell in view.dfa.forward_cells {
                    if cell.next() == NO_DFA_STATE
                        || usize::try_from(cell.next())
                            .ok()
                            .is_some_and(|next| next < complete_rows)
                    {
                        continue;
                    }
                    saw_hole = true;
                    let packed = pack_native_partial_forward_cell(
                        cell.next(),
                        cell.accepted(),
                        usize::try_from(layout.forward_offset).unwrap(),
                        row_bytes,
                        complete_rows,
                        false,
                        None,
                        partial,
                        layout.cells,
                    )
                    .expect("collapsed hole packing");
                    assert_eq!(packed & layout.cells.next_mask(), partial.hole_token_base);
                }
                assert!(saw_hole, "{output:?}/{architecture:?}");
            }

            let serialized = fast.program().serialize().unwrap();
            let table_offset = serialized
                .len()
                .checked_add(15)
                .expect("slow partial table alignment")
                & !15;
            for target in identity_target_matrix() {
                let module = CompiledModule::lower_optimizing_with_limits(
                    fast.program(),
                    target,
                    slow_limits,
                )
                .unwrap_or_else(|error| panic!("slow partial {output:?}/{target:?}: {error}"));
                let report = module
                    .slow_aot_report()
                    .unwrap_or_else(|| panic!("missing slow report: {output:?}/{target:?}"));
                assert!(report.determinization.decline.is_some());
                assert_eq!(
                    report.dfa.build_work,
                    report.determinization.work_completed
                );
                assert!(report.allocation_bytes <= slow_limits.max_allocation_bytes);
                assert!(report.native_data_bytes <= slow_limits.max_native_data_bytes);
                assert_eq!(
                    report.native_data_bytes,
                    module.sections()[PROGRAM_SECTION].bytes().len() - serialized.len(),
                    "alignment padding and table accounting: {output:?}/{target:?}"
                );
                assert_eq!(module.required_runtime_symbol(), Some(RUNTIME_SYMBOL_NAME));
                assert!(module.prepared_entry_symbol().is_none());
                assert_eq!(module.symbols().len(), 5, "{output:?}/{target:?}");
                let table_symbol = &module.symbols()[SLOW_PARTIAL_TABLE_SYMBOL];
                assert_eq!(
                    table_symbol.name,
                    ".Lfre_aot_regex_slow_partial_table_v1"
                );
                assert_eq!(table_symbol.binding, SymbolBinding::Local);
                assert_eq!(table_symbol.kind, SymbolKind::Object);
                assert_eq!(table_symbol.section, Some(PROGRAM_SECTION));
                assert_eq!(table_symbol.offset, u64::try_from(table_offset).unwrap());
                assert_eq!(
                    table_symbol.size,
                    u64::try_from(
                        module.sections()[PROGRAM_SECTION].bytes().len() - table_offset
                    )
                    .unwrap()
                );
                assert!(module.symbols().iter().enumerate().all(|(index, symbol)| {
                    index == SLOW_PARTIAL_TABLE_SYMBOL
                        || (!symbol.name.contains("exclusive")
                            && !symbol.name.contains("partial_table")
                            && !symbol.name.contains("partial_identity"))
                }));
                assert!(module.relocations().iter().all(|relocation| {
                    matches!(
                        relocation.symbol,
                        PROGRAM_SYMBOL | RUNTIME_SYMBOL | SLOW_PARTIAL_TABLE_SYMBOL
                    )
                }));
                assert_eq!(
                    module
                        .relocations()
                        .iter()
                        .filter(|relocation| relocation.symbol == RUNTIME_SYMBOL)
                        .count(),
                    1
                );
                let program_relocations = module
                    .relocations()
                    .iter()
                    .filter(|relocation| relocation.symbol == PROGRAM_SYMBOL)
                    .map(|relocation| (relocation.kind, relocation.addend))
                    .collect::<Vec<_>>();
                let table_relocations = module
                    .relocations()
                    .iter()
                    .filter(|relocation| relocation.symbol == SLOW_PARTIAL_TABLE_SYMBOL)
                    .map(|relocation| (relocation.kind, relocation.addend))
                    .collect::<Vec<_>>();
                let expected_data_relocations = match target.architecture {
                    Architecture::X86_64 => {
                        vec![(RelocationKind::X86PcRelative32, -4)]
                    }
                    Architecture::Aarch64 => vec![
                        (RelocationKind::Aarch64Page21, 0),
                        (RelocationKind::Aarch64PageOff12, 0),
                    ],
                };
                assert_eq!(
                    program_relocations, expected_data_relocations,
                    "wrapper program relocations: {output:?}/{target:?}"
                );
                assert_eq!(
                    table_relocations, expected_data_relocations,
                    "core table relocations: {output:?}/{target:?}"
                );
                assert!(module.sections()[PROGRAM_SECTION]
                    .bytes()
                    .starts_with(&serialized));
            }

            let compiled = crate::compile_with_slow_aot_limits(
                CompileRequest::new(PARTIAL_LOOP_PATTERN, Target::x86_64_linux())
                    .mode(CompileMode::Optimizing)
                    .output(output)
                    .limits(CompileLimitsV1 {
                        determinize: DeterminizeLimits {
                            max_states: 0,
                            ..DeterminizeLimits::default()
                        },
                        ..CompileLimitsV1::default()
                    }),
                slow_limits,
            )
            .expect("receipt-bearing slow partial compile");
            assert!(compiled
                .receipt()
                .slow_aot
                .as_ref()
                .is_some_and(|report| report.determinization.decline.is_some()));
            for pass in [
                crate::OptimizationPass::UniversalOrderedTnfa,
                crate::OptimizationPass::RemoveUnusedReverseMachine,
                crate::OptimizationPass::OutputContractSpecialization,
                crate::OptimizationPass::TargetInstructionSelection,
                crate::OptimizationPass::FixedRegisterAssignment,
                crate::OptimizationPass::CheckedBranchFixup,
                crate::OptimizationPass::RuntimeAdapterLowering,
            ] {
                assert!(compiled.receipt().passes.contains(&pass), "{output:?}/{pass:?}");
            }
        }
    }

    #[test]
    fn slow_partial_local_table_symbol_crosses_arm64_signed24_boundary() {
        const PROGRAM_BYTES: usize = 1 << 23;
        const TABLE_BYTES: usize = 16;
        for target in [
            Target::x86_64_linux(),
            Target::x86_64_macos(),
            Target::aarch64_linux(),
            Target::aarch64_macos(),
        ] {
            let program = vec![0_u8; PROGRAM_BYTES];
            let mut data = program.clone();
            data.extend_from_slice(&[0_u8; TABLE_BYTES]);
            let (code, relocations) = match target.architecture {
                Architecture::X86_64 => (
                    vec![0_u8; 12],
                    vec![
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 0,
                            kind: RelocationKind::X86PcRelative32,
                            symbol: PROGRAM_SYMBOL,
                            addend: -4,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 4,
                            kind: RelocationKind::X86PltRelative32,
                            symbol: RUNTIME_SYMBOL,
                            addend: -4,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 8,
                            kind: RelocationKind::X86PcRelative32,
                            symbol: SLOW_PARTIAL_TABLE_SYMBOL,
                            addend: -4,
                        },
                    ],
                ),
                Architecture::Aarch64 => (
                    vec![0_u8; 20],
                    vec![
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 0,
                            kind: RelocationKind::Aarch64Page21,
                            symbol: PROGRAM_SYMBOL,
                            addend: 0,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 4,
                            kind: RelocationKind::Aarch64PageOff12,
                            symbol: PROGRAM_SYMBOL,
                            addend: 0,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 8,
                            kind: RelocationKind::Aarch64Branch26,
                            symbol: RUNTIME_SYMBOL,
                            addend: 0,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 12,
                            kind: RelocationKind::Aarch64Page21,
                            symbol: SLOW_PARTIAL_TABLE_SYMBOL,
                            addend: 0,
                        },
                        ModuleRelocation {
                            section: TEXT_SECTION,
                            offset: 16,
                            kind: RelocationKind::Aarch64PageOff12,
                            symbol: SLOW_PARTIAL_TABLE_SYMBOL,
                            addend: 0,
                        },
                    ],
                ),
            };
            let lowering = NativeLowering {
                code,
                data,
                relocations,
                slow_partial_table: Some(NativeSlowPartialTableLayout {
                    offset: PROGRAM_BYTES,
                    size: TABLE_BYTES,
                }),
                needs_runtime: true,
                start_accelerator: StartAccelerator::None,
                anchored_prefix_filter_bytes: 0,
            };
            let module = CompiledModule::lower_serialized_with_prelowered(
                program,
                Some(lowering),
                None,
                None,
                false,
                None,
                None,
                None,
                None,
                None,
                target,
            )
            .unwrap_or_else(|error| panic!("large slow table {target:?}: {error}"));
            let table_symbol = &module.symbols()[SLOW_PARTIAL_TABLE_SYMBOL];
            assert_eq!(table_symbol.offset, u64::try_from(PROGRAM_BYTES).unwrap());
            assert_eq!(table_symbol.size, u64::try_from(TABLE_BYTES).unwrap());
            assert!(module
                .relocations()
                .iter()
                .filter(|relocation| relocation.symbol == SLOW_PARTIAL_TABLE_SYMBOL)
                .all(|relocation| relocation.addend <= 0));
            emit_object(&module, ObjectFormat::for_target(target), usize::MAX)
                .unwrap_or_else(|error| panic!("large slow object {target:?}: {error}"));
        }
    }

    #[test]
    fn slow_partial_native_resource_failures_decline_transactionally() {
        assert!(matches!(
            optional_native_lowering_outcome(Err(ObjectError::Allocation(
                "synthetic slow-prefix allocation"
            ))),
            Ok(None)
        ));
        assert!(matches!(
            optional_native_lowering_outcome(Err(ObjectError::Resource {
                resource: crate::CompileResource::ProgramBytes,
                limit: 0,
                required: 1,
            })),
            Ok(None)
        ));
        assert!(matches!(
            optional_native_lowering_outcome(Err(ObjectError::InvalidModule(
                "synthetic structural failure"
            ))),
            Err(ObjectError::InvalidModule("synthetic structural failure"))
        ));

        let target = Target::x86_64_linux();
        let fast = compile(
            CompileRequest::new(PARTIAL_LOOP_PATTERN, target)
                .mode(CompileMode::Fast)
                .output(OutputContract::Exists),
        )
        .expect("fast resource-decline fixture");
        let slow_limits = (1..=64)
            .find_map(|max_states| {
                let limits = slow_partial_limits(max_states);
                let candidate = fast
                    .program()
                    .native_slow_determinized_program(
                        limits.determinize,
                        limits.max_allocation_bytes,
                    )
                    .expect("bounded slow-prefix candidate")?;
                let (complete, discovered) = candidate.retained_dimensions()?;
                (complete > 0 && complete < discovered).then_some(limits)
            })
            .expect("interior slow prefix for resource-decline fixture");
        let declined = CompiledModule::lower_optimizing_with_limits_and_native_data_limit(
            fast.program(),
            target,
            slow_limits,
            0,
        )
        .expect("native-data refusal preserves established fallback");
        let fallback = CompiledModule::lower_k0_optimizing_with_data_limit(
            fast.program(),
            target,
            0,
        )
        .expect("established zero-data fallback");
        assert!(declined.slow_aot_report().is_none());
        assert_eq!(declined.sections(), fallback.sections());
        assert_eq!(declined.symbols(), fallback.symbols());
        assert_eq!(declined.relocations(), fallback.relocations());
    }

    #[test]
    fn slow_late_decline_retains_reverse_for_direct_span_lowering() {
        let pattern = "a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let fast = compile(
            CompileRequest::new(pattern, Target::x86_64_linux())
                .mode(CompileMode::Fast)
                .output(OutputContract::Span),
        )
        .expect("fast variable Span fixture");
        let complete = fast
            .program()
            .native_slow_determinized_program(
                SlowAotLimits::default().determinize,
                SlowAotLimits::default().max_allocation_bytes,
            )
            .expect("complete slow Span determinization")
            .expect("complete slow Span candidate");
        assert!(!complete.is_partial());
        let final_work = complete.report().work_completed;
        let limits = SlowAotLimits {
            determinize: DeterminizeLimits {
                max_work: final_work.checked_sub(1).expect("nonzero slow work"),
                ..SlowAotLimits::default().determinize
            },
            ..SlowAotLimits::default()
        };
        let partial = fast
            .program()
            .native_slow_determinized_program(
                limits.determinize,
                limits.max_allocation_bytes,
            )
            .expect("post-forward slow Span refusal")
            .expect("post-forward transient Span candidate");
        assert!(partial.is_partial());
        let (complete_rows, discovered_states) = partial.retained_dimensions().unwrap();
        assert_eq!(complete_rows, discovered_states);
        assert!(partial.report().decline.as_ref().is_some_and(|decline| {
            matches!(
                decline.stage,
                crate::DeterminizationStage::DfaStateMinimization
                    | crate::DeterminizationStage::AlphabetColumnCoalescing
            )
        }));
        assert!(partial.stats().reverse_states > 0);
        let view = fast.program().native_slow_determinized_view(&partial);
        assert!(!view.collapse_partial_holes);
        assert_eq!(view.partial_discovered_states, None);
        assert_eq!(view.exact_match_width, None);
        for target in [
            Target::x86_64_linux(),
            Target::x86_64_macos(),
            Target::aarch64_linux(),
            Target::aarch64_macos(),
        ] {
            let (_, layout) = build_native_dfa_table_for_architecture(view, target.architecture)
                .expect("direct retained-reverse Span layout");
            assert!(layout.partial.is_none());
            assert!(layout.has_reverse);
            assert!(layout.exact_span_width.is_none());
            let module = CompiledModule::lower_optimizing_with_limits(
                fast.program(),
                target,
                limits,
            )
            .expect("retained-reverse slow Span module");
            let report = module
                .slow_aot_report()
                .unwrap_or_else(|| panic!("missing slow report: {target:?}"));
            assert!(report.determinization.decline.is_some());
            assert!(report.dfa.reverse_states > 0);
            assert_eq!(
                report.native_data_bytes,
                module.sections()[PROGRAM_SECTION].bytes().len()
            );
            assert!(module.required_runtime_symbol().is_none());
            assert!(module.prepared_entry_symbol().is_none());
            assert_eq!(module.symbols().len(), 2);
            assert!(module
                .relocations()
                .iter()
                .all(|relocation| relocation.symbol == PROGRAM_SYMBOL));
        }

        let compiled = crate::compile_with_slow_aot_limits(
            CompileRequest::new(pattern, Target::x86_64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Span)
                .limits(CompileLimitsV1 {
                    determinize: DeterminizeLimits {
                        max_states: 0,
                        ..DeterminizeLimits::default()
                    },
                    ..CompileLimitsV1::default()
                }),
            limits,
        )
        .expect("receipt-bearing retained-reverse slow compile");
        assert!(!compiled.receipt().runtime_helper_required);
        assert!(compiled
            .receipt()
            .passes
            .contains(&crate::OptimizationPass::ReverseStartRecovery));
        assert!(compiled
            .receipt()
            .passes
            .contains(&crate::OptimizationPass::DfaStateMinimization));
        assert!(!compiled
            .receipt()
            .passes
            .contains(&crate::OptimizationPass::RuntimeAdapterLowering));
    }

    #[test]
    fn slow_partial_forward_minimization_is_receipted_once() {
        let pattern = "a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let fast = compile(
            CompileRequest::new(pattern, Target::x86_64_linux())
                .mode(CompileMode::Fast)
                .output(OutputContract::Span),
        )
        .expect("fast minimization-provenance fixture");
        let limits = slow_forward_minimized_reverse_decline_limits(fast.program());
        let module = CompiledModule::lower_optimizing_with_limits(
            fast.program(),
            Target::x86_64_linux(),
            limits,
        )
        .expect("direct mixed-minimization slow module");
        assert!(module.slow_retained_forward_minimized());
        assert!(module.required_runtime_symbol().is_none());

        let compiled = crate::compile_with_slow_aot_limits(
            CompileRequest::new(pattern, Target::x86_64_linux())
                .mode(CompileMode::Optimizing)
                .output(OutputContract::Span)
                .limits(CompileLimitsV1 {
                    determinize: DeterminizeLimits {
                        max_states: 0,
                        ..DeterminizeLimits::default()
                    },
                    ..CompileLimitsV1::default()
                }),
            limits,
        )
        .expect("receipt-bearing mixed-minimization slow module");
        let slow = compiled.receipt().slow_aot.as_ref().expect("slow receipt");
        assert!(!slow.determinization.completed_stages.contains(
            &crate::DeterminizationStage::DfaStateMinimization
        ));
        assert!(compiled.module().slow_retained_forward_minimized());
        assert!(!compiled.receipt().runtime_helper_required);
        assert_eq!(
            compiled
                .receipt()
                .passes
                .iter()
                .filter(|&&pass| pass == crate::OptimizationPass::DfaStateMinimization)
                .count(),
            1
        );
        let reverse_position = compiled
            .receipt()
            .passes
            .iter()
            .position(|&pass| pass == crate::OptimizationPass::ReverseStartRecovery)
            .expect("reverse recovery receipt");
        let minimization_position = compiled
            .receipt()
            .passes
            .iter()
            .position(|&pass| pass == crate::OptimizationPass::DfaStateMinimization)
            .expect("partial forward minimization receipt");
        assert!(reverse_position < minimization_position);
    }

